// Hypothesized former/future North Pole position (Np') and its antipode (Sp')
const NP_PRIME = { lat: -14, lng: 31 };
const SP_PRIME = { lat: 14, lng: -149 };

// Angular distance in degrees between two points on a sphere
const angularDistance = (lat1, lng1, lat2, lng2) => {
  const toRad = d => d * Math.PI / 180;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  return (2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a))) * 180 / Math.PI;
};

// Minimum angular distance to Np' or Sp'; returns { dist, pole }
const poleProximity = (lat, lng) => {
  const dNp = angularDistance(lat, lng, NP_PRIME.lat, NP_PRIME.lng);
  const dSp = angularDistance(lat, lng, SP_PRIME.lat, SP_PRIME.lng);
  return dNp <= dSp ? { dist: dNp, pole: "Np\u2032" } : { dist: dSp, pole: "Sp\u2032" };
};

const POLE_PROXIMITY_THRESHOLD = 20; // degrees — azimuth unreliable within this

// Calculate initial bearing from point A to point B (degrees)
const calcBearing = (lat1, lng1, lat2, lng2) => {
  const toRad = d => d * Math.PI / 180;
  const toDeg = r => r * 180 / Math.PI;
  const dLng = toRad(lng2 - lng1);
  const y = Math.sin(dLng) * Math.cos(toRad(lat2));
  const x = Math.cos(toRad(lat1)) * Math.sin(toRad(lat2)) - Math.sin(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.cos(dLng);
  return ((toDeg(Math.atan2(y, x)) % 360) + 360) % 360;
};

// Interpolate great circle arc as array of [lat,lng] pairs
const interpolateGreatCircle = (lat1, lng1, lat2, lng2, numPoints = 60) => {
  const toRad = d => d * Math.PI / 180;
  const toDeg = r => r * 180 / Math.PI;
  const phi1 = toRad(lat1), lam1 = toRad(lng1);
  const phi2 = toRad(lat2), lam2 = toRad(lng2);
  // Angular distance (haversine)
  const d = 2 * Math.asin(Math.sqrt(
    Math.pow(Math.sin((phi2 - phi1) / 2), 2) +
    Math.cos(phi1) * Math.cos(phi2) * Math.pow(Math.sin((lam2 - lam1) / 2), 2)
  ));
  if (d < 1e-10) return [[lat1, lng1], [lat2, lng2]];
  const points = [];
  for (let i = 0; i <= numPoints; i++) {
    const f = i / numPoints;
    const A = Math.sin((1 - f) * d) / Math.sin(d);
    const B = Math.sin(f * d) / Math.sin(d);
    const x = A * Math.cos(phi1) * Math.cos(lam1) + B * Math.cos(phi2) * Math.cos(lam2);
    const y = A * Math.cos(phi1) * Math.sin(lam1) + B * Math.cos(phi2) * Math.sin(lam2);
    const z = A * Math.sin(phi1) + B * Math.sin(phi2);
    points.push([toDeg(Math.atan2(z, Math.sqrt(x * x + y * y))), toDeg(Math.atan2(y, x))]);
  }
  return points;
};

// Globe component using CesiumJS
const GlobeView = ({ seismicEvents, volcData }) => {
  const cesiumContainerRef = useRef(null);
  const viewerRef = useRef(null);
  const dataSourcesRef = useRef({});
  const [selectedPoint, setSelectedPoint] = useState(null);
  const [monuments, setMonuments] = useState([]);
  const [verified, setVerified] = useState(() => new Map());
  const [holoceneVolcanoes, setHoloceneVolcanoes] = useState([]);
  const [layers, setLayers] = useState({
    plates: true, earthquakes: true, volcanoes: true, allVolcanoes: false,
    stations: true, monuments: true, bearingLines: true,
  });
  const [monListOpen, setMonListOpen] = useState(false);
  const [monSections, setMonSections] = useState({ verified: true, plausible: true, unconfirmed: true });
  const [axisMode, setAxisMode] = useState(null);       // null or { monumentName, lat, lng }
  const [axisPreview, setAxisPreview] = useState(null);  // null or { lat, lng }
  const [measuredAxes, setMeasuredAxes] = useState(() => new Map());
  const [pinMode, setPinMode] = useState(null);          // null or { monumentName, origLat, origLng }
  const [pinOverrides, setPinOverrides] = useState(() => new Map());
  const [customPins, setCustomPins] = useState([]);
  const [hiddenPins, setHiddenPins] = useState(() => new Set());
  const [addPinMode, setAddPinMode] = useState(false);
  const [addPinForm, setAddPinForm] = useState(null);
  const [addPinError, setAddPinError] = useState(null);
  const [monSearchQuery, setMonSearchQuery] = useState('');
  const [monSortBy, setMonSortBy] = useState('alpha');
  const [monFilterUnmeasured, setMonFilterUnmeasured] = useState(false);
  const [removeConfirm, setRemoveConfirm] = useState(null);
  const axisModeRef = useRef(null);
  const pinModeRef = useRef(null);
  const addPinModeRef = useRef(false);
  const previewEntityRef = useRef(null);

  useEffect(() => { axisModeRef.current = axisMode; }, [axisMode]);
  useEffect(() => { pinModeRef.current = pinMode; }, [pinMode]);
  useEffect(() => { addPinModeRef.current = addPinMode; }, [addPinMode]);

  // Resolve a monument's effective position (override or original)
  const resolvePin = (m) => {
    const ov = pinOverrides.get(m.name);
    return ov ? { lat: ov.lat, lng: ov.lng } : { lat: m.lat, lng: m.lng };
  };

  const startAxisDrawing = (monumentName, lat, lng) => {
    setAxisMode({ monumentName, lat, lng });
    setAxisPreview(null);
  };

  const startPinReplace = (monumentName, lat, lng) => {
    setPinMode({ monumentName, origLat: lat, origLng: lng });
  };

  // Load monuments data
  useEffect(() => {
    fetch('./assets/monuments.json?v=' + Date.now())
      .then(r => r.ok ? r.json() : [])
      .then(data => {
        const arr = Array.isArray(data) ? data : [];
        setMonuments(arr);
      })
      .catch(() => {});
    // Load all Holocene volcanoes
    fetch('./assets/holocene_volcanoes.json?v=' + Date.now())
      .then(r => r.ok ? r.json() : [])
      .then(data => { if (Array.isArray(data)) setHoloceneVolcanoes(data); })
      .catch(() => {});
  }, []);

  // Load hidden pins from localStorage
  useEffect(() => {
    try {
      const arr = JSON.parse(localStorage.getItem('ecdo-watch-hidden-pins') || '[]');
      setHiddenPins(new Set(arr));
    } catch {}
  }, []);

  // Effective monument list: baseline minus hidden, plus custom
  const effectiveMonuments = useMemo(() => [
    ...monuments.filter(m => !hiddenPins.has(m.name)),
    ...customPins,
  ], [monuments, hiddenPins, customPins]);

  // Load shared measurements baseline, then overlay localStorage draft
  useEffect(() => {
    fetch('./assets/measurements.json?v=' + Date.now())
      .then(r => r.ok ? r.json() : {})
      .then(shared => {
        // Helper: merge shared baseline with localStorage overrides
        const mergeLayer = (sharedObj, localKey) => {
          const base = sharedObj || {};
          try {
            const local = JSON.parse(localStorage.getItem(localKey) || '{}');
            return { ...base, ...local };
          } catch { return base; }
        };

        const mergedVerified = mergeLayer(shared.verified, 'ecdo-watch-verified');
        const mergedAxes = mergeLayer(shared.axes, 'ecdo-watch-axes');
        const mergedPins = mergeLayer(shared.pins, 'ecdo-watch-pins');

        setVerified(new Map(Object.entries(mergedVerified)));
        setMeasuredAxes(new Map(Object.entries(mergedAxes)));
        setPinOverrides(new Map(Object.entries(mergedPins)));

        // Merge custom pins: shared baseline + localStorage additions (dedupe by name)
        const sharedCustom = Array.isArray(shared.customPins) ? shared.customPins : [];
        try {
          const localCustom = JSON.parse(localStorage.getItem('ecdo-watch-custom-pins') || '[]');
          const seen = new Set();
          const merged = [];
          [...sharedCustom, ...localCustom].forEach(p => {
            if (p.name && !seen.has(p.name)) { seen.add(p.name); merged.push(p); }
          });
          setCustomPins(merged);
        } catch { setCustomPins(sharedCustom); }
      })
      .catch(() => {
        // Fallback: load from localStorage only
        try { setVerified(new Map(Object.entries(JSON.parse(localStorage.getItem('ecdo-watch-verified') || '{}')))); } catch {}
        try { setMeasuredAxes(new Map(Object.entries(JSON.parse(localStorage.getItem('ecdo-watch-axes') || '{}')))); } catch {}
        try { setPinOverrides(new Map(Object.entries(JSON.parse(localStorage.getItem('ecdo-watch-pins') || '{}')))); } catch {}
        try { setCustomPins(JSON.parse(localStorage.getItem('ecdo-watch-custom-pins') || '[]')); } catch {}
      });
  }, []);

  // CesiumJS Viewer init (runs once)
  useEffect(() => {
    if (!cesiumContainerRef.current || typeof Cesium === 'undefined') return;
    if (viewerRef.current) return;

    const viewer = new Cesium.Viewer(cesiumContainerRef.current, {
      baseLayer: false,
      terrainProvider: new Cesium.EllipsoidTerrainProvider(),
      baseLayerPicker: false,
      geocoder: false,
      homeButton: false,
      sceneModePicker: false,
      navigationHelpButton: false,
      animation: false,
      timeline: false,
      fullscreenButton: false,
      infoBox: false,
      selectionIndicator: false,
    });

    // Add ESRI World Imagery manually (avoids Promise-in-constructor issues)
    Cesium.ArcGisMapServerImageryProvider.fromUrl(
      'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer'
    ).then(provider => {
      if (!viewer.isDestroyed()) {
        viewer.imageryLayers.addImageryProvider(provider);
      }
    }).catch(() => {});

    viewer.scene.backgroundColor = Cesium.Color.fromCssColorString('#08080c');
    if (viewer.scene.skyBox) viewer.scene.skyBox.show = false;
    if (viewer.scene.sun) viewer.scene.sun.show = false;
    if (viewer.scene.moon) viewer.scene.moon.show = false;
    viewer.scene.skyAtmosphere.show = true;

    // Initial camera (lat:10, lng:170)
    viewer.camera.setView({
      destination: Cesium.Cartesian3.fromDegrees(170, 10, 20000000),
    });

    // Create CustomDataSources for each layer
    const ds = {
      plates: new Cesium.CustomDataSource('plates'),
      earthquakes: new Cesium.CustomDataSource('earthquakes'),
      volcanoes: new Cesium.CustomDataSource('volcanoes'),
      allVolcanoes: new Cesium.CustomDataSource('allVolcanoes'),
      stations: new Cesium.CustomDataSource('stations'),
      monuments: new Cesium.CustomDataSource('monuments'),
      bearingLines: new Cesium.CustomDataSource('bearingLines'),
      measuredAxes: new Cesium.CustomDataSource('measuredAxes'),
    };
    Object.values(ds).forEach(d => viewer.dataSources.add(d));
    dataSourcesRef.current = ds;

    // Click handler
    const handler = new Cesium.ScreenSpaceEventHandler(viewer.canvas);
    handler.setInputAction((click) => {
      if (axisModeRef.current || pinModeRef.current || addPinModeRef.current) return;
      const picked = viewer.scene.pick(click.position);
      if (Cesium.defined(picked) && picked.id && picked.id._customData) {
        setSelectedPoint(picked.id._customData);
      } else {
        setSelectedPoint(null);
      }
    }, Cesium.ScreenSpaceEventType.LEFT_CLICK);

    viewerRef.current = viewer;

    // Fetch tectonic plates -> add to ds.plates as polyline entities
    fetch('https://raw.githubusercontent.com/fraxen/tectonicplates/master/GeoJSON/PB2002_boundaries.json')
      .then(r => r.ok ? r.json() : null)
      .then(data => {
        if (!data || !data.features) return;
        data.features.forEach(f => {
          const lines = f.geometry.type === 'MultiLineString'
            ? f.geometry.coordinates : [f.geometry.coordinates];
          lines.forEach(line => {
            const flat = line.flatMap(([lng, lat]) => [lng, lat]);
            ds.plates.entities.add({
              polyline: {
                positions: Cesium.Cartesian3.fromDegreesArray(flat),
                width: 1,
                material: Cesium.Color.fromCssColorString('rgba(245, 158, 11, 0.3)'),
                clampToGround: true,
              },
            });
          });
        });
      })
      .catch(() => {});

    return () => {
      handler.destroy();
      viewer.destroy();
      viewerRef.current = null;
    };
  }, []);

  // Update data layers when data or toggles change
  useEffect(() => {
    const ds = dataSourcesRef.current;
    if (!ds.earthquakes) return;

    // Clear dynamic data sources (not plates — those are static from init)
    ds.earthquakes.entities.removeAll();
    ds.volcanoes.entities.removeAll();
    ds.allVolcanoes.entities.removeAll();
    ds.stations.entities.removeAll();
    ds.monuments.entities.removeAll();
    ds.bearingLines.entities.removeAll();
    ds.measuredAxes.entities.removeAll();
    previewEntityRef.current = null;

    // 1. Earthquake epicenters (purple) - scaled by magnitude
    if (seismicEvents && seismicEvents.events) {
      seismicEvents.events.forEach(ev => {
        const color = ev.mag >= 6.0 ? '#c084fc' : ev.mag >= 5.0 ? '#a78bfa' : '#8b5cf6';
        ds.earthquakes.entities.add({
          position: Cesium.Cartesian3.fromDegrees(ev.lon, ev.lat),
          point: {
            pixelSize: Math.max(5, (ev.mag - 3.5) * 4),
            color: Cesium.Color.fromCssColorString(color),
            outlineColor: Cesium.Color.WHITE,
            outlineWidth: 0.5,
          },
          _customData: {
            type: 'earthquake', lat: ev.lat, lng: ev.lon,
            mag: ev.mag, depth_km: ev.depth_km,
            date: ev.date, datetime: ev.datetime || ev.date,
          },
        });
      });
    }

    // 2a. All Holocene volcanoes (dim orange, smaller)
    if (holoceneVolcanoes.length > 0) {
      const activeNames = new Set((volcData && volcData.current_volcanoes || []).map(v => v.name));
      holoceneVolcanoes.forEach(v => {
        if (activeNames.has(v.name)) return; // skip active ones (shown in layer above)
        ds.allVolcanoes.entities.add({
          position: Cesium.Cartesian3.fromDegrees(v.lon, v.lat),
          point: {
            pixelSize: 4,
            color: Cesium.Color.fromCssColorString('rgba(239,68,68,0.25)'),
            outlineColor: Cesium.Color.fromCssColorString('rgba(255,255,255,0.15)'),
            outlineWidth: 0.5,
          },
          _customData: {
            type: 'volcano', lat: v.lat, lng: v.lon,
            vName: v.name, vStatus: 'holocene',
            vType: v.type || null,
            vElevation: v.elevation || null,
            vLastEruption: v.last_eruption || null,
            vCountry: v.country || null,
          },
        });
      });
    }

    // 2b. Active volcanoes (red)
    if (volcData && volcData.current_volcanoes) {
      volcData.current_volcanoes.forEach(v => {
        ds.volcanoes.entities.add({
          position: Cesium.Cartesian3.fromDegrees(v.lon, v.lat),
          point: {
            pixelSize: 6,
            color: Cesium.Color.fromCssColorString('#ef4444'),
            outlineColor: Cesium.Color.WHITE,
            outlineWidth: 0.5,
          },
          _customData: {
            type: 'volcano', lat: v.lat, lng: v.lon,
            vName: v.name, vStatus: v.status,
            vStartDate: v.start_date || null,
            vVei: v.vei != null ? v.vei : null,
          },
        });
      });
    }

    // 3. Magnetometer stations (blue)
    MAG_STATION_COORDS.forEach(s => {
      ds.stations.entities.add({
        position: Cesium.Cartesian3.fromDegrees(s.lng, s.lat),
        point: {
          pixelSize: 6,
          color: Cesium.Color.fromCssColorString('#4a9eff'),
          outlineColor: Cesium.Color.WHITE,
          outlineWidth: 0.5,
        },
        _customData: {
          type: 'station', lat: s.lat, lng: s.lng,
          sCode: s.code, sName: s.name,
        },
      });
    });

    // 4. Ancient monuments (gold; plausible = yellow outline, verified = green outline)
    effectiveMonuments.forEach(m => {
      const pin = resolvePin(m);
      const mStatus = verified.get(m.name); // undefined | 'plausible' | 'verified'
      const outlineColor = mStatus === 'verified' ? '#22c55e' : mStatus === 'plausible' ? '#eab308' : '#ffffff';
      const outlineWidth = mStatus ? 2.5 : 1.5;
      ds.monuments.entities.add({
        position: Cesium.Cartesian3.fromDegrees(pin.lng, pin.lat),
        point: {
          pixelSize: 8,
          color: Cesium.Color.fromCssColorString('#f59e0b'),
          outlineColor: Cesium.Color.fromCssColorString(outlineColor),
          outlineWidth,
        },
        _customData: {
          type: 'monument', lat: pin.lat, lng: pin.lng,
          mName: m.name, mRegion: m.region,
          mAge: m.est_age, mNotes: m.notes,
          mStatus, pinOverridden: pinOverrides.has(m.name),
          _custom: !!m._custom,
        },
      });
    });

    // Np' special marker (green)
    ds.monuments.entities.add({
      position: Cesium.Cartesian3.fromDegrees(NP_PRIME.lng, NP_PRIME.lat),
      point: {
        pixelSize: 10,
        color: Cesium.Color.fromCssColorString('#22c55e'),
        outlineColor: Cesium.Color.WHITE,
        outlineWidth: 2,
      },
      _customData: {
        type: 'np_prime', lat: NP_PRIME.lat, lng: NP_PRIME.lng,
      },
    });

    // Sp' special marker (amber)
    ds.monuments.entities.add({
      position: Cesium.Cartesian3.fromDegrees(SP_PRIME.lng, SP_PRIME.lat),
      point: {
        pixelSize: 10,
        color: Cesium.Color.fromCssColorString('#f59e0b'),
        outlineColor: Cesium.Color.WHITE,
        outlineWidth: 2,
      },
      _customData: {
        type: 'sp_prime', lat: SP_PRIME.lat, lng: SP_PRIME.lng,
      },
    });

    // 5. Bearing lines: measured axis (cyan solid) + ideal to Np' (gold dashed) for comparison
    effectiveMonuments.forEach(m => {
      const pin = resolvePin(m);
      const axis = measuredAxes.get(m.name);
      if (!axis) return; // No tautological line — only show when measured axis exists
      // Measured axis line (cyan solid)
      const measuredArc = interpolateGreatCircle(pin.lat, pin.lng, axis.endLat, axis.endLng);
      const measuredFlat = measuredArc.flatMap(([lat, lng]) => [lng, lat]);
      ds.bearingLines.entities.add({
        polyline: {
          positions: Cesium.Cartesian3.fromDegreesArray(measuredFlat),
          width: 2,
          material: Cesium.Color.fromCssColorString('#00e5ff').withAlpha(0.85),
          clampToGround: true,
        },
      });
      // Ideal line to Np' (gold dashed) for comparison
      const idealArc = interpolateGreatCircle(pin.lat, pin.lng, NP_PRIME.lat, NP_PRIME.lng);
      const idealFlat = idealArc.flatMap(([lat, lng]) => [lng, lat]);
      ds.bearingLines.entities.add({
        polyline: {
          positions: Cesium.Cartesian3.fromDegreesArray(idealFlat),
          width: 1.5,
          material: new Cesium.PolylineDashMaterialProperty({
            color: Cesium.Color.fromCssColorString('#f59e0b').withAlpha(0.6),
            dashLength: 12,
          }),
          clampToGround: true,
        },
      });
    });

    // Sync layer visibility
    ds.plates.show = layers.plates;
    ds.earthquakes.show = layers.earthquakes;
    ds.volcanoes.show = layers.volcanoes;
    ds.allVolcanoes.show = layers.allVolcanoes;
    ds.stations.show = layers.stations;
    ds.monuments.show = layers.monuments;
    ds.bearingLines.show = layers.bearingLines;
    ds.measuredAxes.show = layers.bearingLines;

  }, [seismicEvents, volcData, holoceneVolcanoes, layers, effectiveMonuments, verified, measuredAxes, pinOverrides]);

  // Fly to clicked monument
  useEffect(() => {
    if (!selectedPoint || !viewerRef.current) return;
    const d = selectedPoint;
    const lng = d.lng != null ? d.lng : d.lon;
    if (lng == null || d.lat == null) return;
    viewerRef.current.camera.flyTo({
      destination: Cesium.Cartesian3.fromDegrees(lng, d.lat, 50000),
      duration: 1.0,
    });
  }, [selectedPoint]);

  // Axis-drawing mode: register event handlers
  useEffect(() => {
    const viewer = viewerRef.current;
    if (!viewer || !axisMode) return;

    const container = cesiumContainerRef.current;
    if (container) container.style.cursor = 'crosshair';

    const drawHandler = new Cesium.ScreenSpaceEventHandler(viewer.canvas);

    // MOUSE_MOVE: update preview endpoint
    drawHandler.setInputAction((movement) => {
      const ray = viewer.camera.getPickRay(movement.endPosition);
      if (!ray) return;
      const cartesian = viewer.scene.globe.pick(ray, viewer.scene);
      if (!cartesian) return;
      const carto = Cesium.Cartographic.fromCartesian(cartesian);
      setAxisPreview({
        lat: Cesium.Math.toDegrees(carto.latitude),
        lng: Cesium.Math.toDegrees(carto.longitude),
      });
    }, Cesium.ScreenSpaceEventType.MOUSE_MOVE);

    // LEFT_CLICK: finalize axis
    drawHandler.setInputAction((click) => {
      const ray = viewer.camera.getPickRay(click.position);
      if (!ray) return;
      const cartesian = viewer.scene.globe.pick(ray, viewer.scene);
      if (!cartesian) return;
      const carto = Cesium.Cartographic.fromCartesian(cartesian);
      const endLat = Cesium.Math.toDegrees(carto.latitude);
      const endLng = Cesium.Math.toDegrees(carto.longitude);
      const mode = axisModeRef.current;
      if (!mode) return;
      const bearing = calcBearing(mode.lat, mode.lng, endLat, endLng);
      setMeasuredAxes(prev => {
        const next = new Map(prev);
        next.set(mode.monumentName, { endLat, endLng, bearing });
        localStorage.setItem('ecdo-watch-axes', JSON.stringify(Object.fromEntries(next)));
        return next;
      });
      setAxisMode(null);
      setAxisPreview(null);
    }, Cesium.ScreenSpaceEventType.LEFT_CLICK);

    // RIGHT_CLICK: cancel
    drawHandler.setInputAction(() => {
      setAxisMode(null);
      setAxisPreview(null);
    }, Cesium.ScreenSpaceEventType.RIGHT_CLICK);

    // Escape key: cancel
    const onKeyDown = (e) => {
      if (e.key === 'Escape') {
        setAxisMode(null);
        setAxisPreview(null);
      }
    };
    document.addEventListener('keydown', onKeyDown);

    return () => {
      drawHandler.destroy();
      document.removeEventListener('keydown', onKeyDown);
      if (container) container.style.cursor = 'grab';
    };
  }, [axisMode]);

  // Preview line: draw cyan polyline from monument to cursor
  useEffect(() => {
    const ds = dataSourcesRef.current;
    if (!ds.measuredAxes) return;
    // Remove old preview
    if (previewEntityRef.current) {
      ds.measuredAxes.entities.remove(previewEntityRef.current);
      previewEntityRef.current = null;
    }
    if (!axisMode || !axisPreview) return;
    const arcPts = interpolateGreatCircle(axisMode.lat, axisMode.lng, axisPreview.lat, axisPreview.lng);
    const flat = arcPts.flatMap(([lat, lng]) => [lng, lat]);
    const entity = ds.measuredAxes.entities.add({
      polyline: {
        positions: Cesium.Cartesian3.fromDegreesArray(flat),
        width: 2,
        material: Cesium.Color.fromCssColorString('#00e5ff').withAlpha(0.7),
        clampToGround: true,
      },
    });
    previewEntityRef.current = entity;
  }, [axisMode, axisPreview]);

  // Pin-replace mode: click globe to reposition a monument pin
  useEffect(() => {
    const viewer = viewerRef.current;
    if (!viewer || !pinMode) return;

    const container = cesiumContainerRef.current;
    if (container) container.style.cursor = 'crosshair';

    const pinHandler = new Cesium.ScreenSpaceEventHandler(viewer.canvas);

    // LEFT_CLICK: place pin at new position
    pinHandler.setInputAction((click) => {
      const ray = viewer.camera.getPickRay(click.position);
      if (!ray) return;
      const cartesian = viewer.scene.globe.pick(ray, viewer.scene);
      if (!cartesian) return;
      const carto = Cesium.Cartographic.fromCartesian(cartesian);
      const newLat = Cesium.Math.toDegrees(carto.latitude);
      const newLng = Cesium.Math.toDegrees(carto.longitude);
      const mode = pinModeRef.current;
      if (!mode) return;
      setPinOverrides(prev => {
        const next = new Map(prev);
        next.set(mode.monumentName, { lat: newLat, lng: newLng });
        localStorage.setItem('ecdo-watch-pins', JSON.stringify(Object.fromEntries(next)));
        return next;
      });
      // Update selectedPoint so the info panel reflects new coords
      setSelectedPoint(prev => prev && prev.mName === mode.monumentName
        ? { ...prev, lat: newLat, lng: newLng, pinOverridden: true }
        : prev
      );
      setPinMode(null);
    }, Cesium.ScreenSpaceEventType.LEFT_CLICK);

    // RIGHT_CLICK: cancel
    pinHandler.setInputAction(() => { setPinMode(null); }, Cesium.ScreenSpaceEventType.RIGHT_CLICK);

    // Escape key: cancel
    const onKeyDown = (e) => { if (e.key === 'Escape') setPinMode(null); };
    document.addEventListener('keydown', onKeyDown);

    return () => {
      pinHandler.destroy();
      document.removeEventListener('keydown', onKeyDown);
      if (container) container.style.cursor = 'grab';
    };
  }, [pinMode]);

  // Add-pin mode: click globe to place a new custom pin
  useEffect(() => {
    const viewer = viewerRef.current;
    if (!viewer || !addPinMode) return;

    const container = cesiumContainerRef.current;
    if (container) container.style.cursor = 'crosshair';

    const addHandler = new Cesium.ScreenSpaceEventHandler(viewer.canvas);

    addHandler.setInputAction((click) => {
      const ray = viewer.camera.getPickRay(click.position);
      if (!ray) return;
      const cartesian = viewer.scene.globe.pick(ray, viewer.scene);
      if (!cartesian) return;
      const carto = Cesium.Cartographic.fromCartesian(cartesian);
      const lat = parseFloat(Cesium.Math.toDegrees(carto.latitude).toFixed(4));
      const lng = parseFloat(Cesium.Math.toDegrees(carto.longitude).toFixed(4));
      setAddPinForm({ lat, lng });
      setAddPinMode(false);
    }, Cesium.ScreenSpaceEventType.LEFT_CLICK);

    addHandler.setInputAction(() => { setAddPinMode(false); }, Cesium.ScreenSpaceEventType.RIGHT_CLICK);

    const onKeyDown = (e) => { if (e.key === 'Escape') setAddPinMode(false); };
    document.addEventListener('keydown', onKeyDown);

    return () => {
      addHandler.destroy();
      document.removeEventListener('keydown', onKeyDown);
      if (container) container.style.cursor = 'grab';
    };
  }, [addPinMode]);

  // Global Escape handler: close info panel when no drawing mode is active
  useEffect(() => {
    const onKeyDown = (e) => {
      if (e.key === 'Escape' && !axisModeRef.current && !pinModeRef.current && !addPinModeRef.current) {
        if (addPinForm) {
          setAddPinForm(null);
          setAddPinError(null);
        } else if (removeConfirm) {
          setRemoveConfirm(null);
        } else if (selectedPoint) {
          setSelectedPoint(null);
        }
      }
    };
    document.addEventListener('keydown', onKeyDown);
    return () => document.removeEventListener('keydown', onKeyDown);
  }, [selectedPoint, addPinForm, removeConfirm]);

  const toggleLayer = (key) => {
    setLayers(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const exportMeasurements = () => {
    const data = {
      axes: Object.fromEntries(measuredAxes),
      pins: Object.fromEntries(pinOverrides),
      verified: Object.fromEntries(verified),
      customPins,
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'measurements.json';
    a.click();
    URL.revokeObjectURL(url);
  };

  const removePin = (name, isCustom) => {
    // Clean up associated data
    setMeasuredAxes(prev => {
      const next = new Map(prev);
      if (next.has(name)) { next.delete(name); localStorage.setItem('ecdo-watch-axes', JSON.stringify(Object.fromEntries(next))); }
      return next;
    });
    setPinOverrides(prev => {
      const next = new Map(prev);
      if (next.has(name)) { next.delete(name); localStorage.setItem('ecdo-watch-pins', JSON.stringify(Object.fromEntries(next))); }
      return next;
    });
    setVerified(prev => {
      const next = new Map(prev);
      if (next.has(name)) { next.delete(name); localStorage.setItem('ecdo-watch-verified', JSON.stringify(Object.fromEntries(next))); }
      return next;
    });
    if (isCustom) {
      setCustomPins(prev => {
        const next = prev.filter(p => p.name !== name);
        localStorage.setItem('ecdo-watch-custom-pins', JSON.stringify(next));
        return next;
      });
    } else {
      setHiddenPins(prev => {
        const next = new Set(prev);
        next.add(name);
        localStorage.setItem('ecdo-watch-hidden-pins', JSON.stringify([...next]));
        return next;
      });
    }
    setSelectedPoint(null);
  };

  const cycleVerified = (name) => {
    setVerified(prev => {
      const next = new Map(prev);
      const cur = next.get(name);
      if (!cur) next.set(name, 'plausible');
      else if (cur === 'plausible') next.set(name, 'verified');
      else next.delete(name);
      localStorage.setItem('ecdo-watch-verified', JSON.stringify(Object.fromEntries(next)));
      return next;
    });
  };

  return (
    <div style={{ position: 'relative', height: '100%', minHeight: 400, overflow: 'hidden' }}>

      {/* Cesium container — absolutely positioned to prevent layout feedback loop */}
      <div
        ref={cesiumContainerRef}
        style={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, cursor: 'grab' }}
      />

      {/* Axis drawing mode banner */}
      {axisMode && (
        <div style={{
          position: 'absolute', top: 12, left: '50%', transform: 'translateX(-50%)',
          zIndex: 1100, background: 'rgba(0,229,255,0.12)', border: '1px solid #00e5ff',
          borderRadius: 8, padding: '10px 20px', textAlign: 'center',
          backdropFilter: 'blur(8px)', pointerEvents: 'none',
        }}>
          <div style={{ color: '#00e5ff', fontFamily: 'monospace', fontWeight: 700, fontSize: 13, letterSpacing: 1 }}>
            AXIS DRAWING MODE
          </div>
          <div style={{ color: '#e8e8ed', fontSize: 11, marginTop: 4 }}>
            Click on the globe to set the axis endpoint for <span style={{ color: '#00e5ff', fontWeight: 600 }}>{axisMode.monumentName}</span>
          </div>
          <div style={{ color: '#7a7a8c', fontSize: 10, marginTop: 2 }}>
            Right-click or Esc to cancel
          </div>
        </div>
      )}

      {/* Pin replace mode banner */}
      {pinMode && (
        <div style={{
          position: 'absolute', top: 12, left: '50%', transform: 'translateX(-50%)',
          zIndex: 1100, background: 'rgba(245,158,11,0.12)', border: '1px solid #f59e0b',
          borderRadius: 8, padding: '10px 20px', textAlign: 'center',
          backdropFilter: 'blur(8px)', pointerEvents: 'none',
        }}>
          <div style={{ color: '#f59e0b', fontFamily: 'monospace', fontWeight: 700, fontSize: 13, letterSpacing: 1 }}>
            PIN REPLACE MODE
          </div>
          <div style={{ color: '#e8e8ed', fontSize: 11, marginTop: 4 }}>
            Click on the globe to reposition <span style={{ color: '#f59e0b', fontWeight: 600 }}>{pinMode.monumentName}</span>
          </div>
          <div style={{ color: '#7a7a8c', fontSize: 10, marginTop: 2 }}>
            Right-click or Esc to cancel
          </div>
        </div>
      )}

      {/* Add pin mode banner */}
      {addPinMode && (
        <div style={{
          position: 'absolute', top: 12, left: '50%', transform: 'translateX(-50%)',
          zIndex: 1100, background: 'rgba(34,197,94,0.12)', border: '1px solid #22c55e',
          borderRadius: 8, padding: '10px 20px', textAlign: 'center',
          backdropFilter: 'blur(8px)', pointerEvents: 'none',
        }}>
          <div style={{ color: '#22c55e', fontFamily: 'monospace', fontWeight: 700, fontSize: 13, letterSpacing: 1 }}>
            ADD PIN MODE
          </div>
          <div style={{ color: '#e8e8ed', fontSize: 11, marginTop: 4 }}>
            Click on the globe to place a new pin
          </div>
          <div style={{ color: '#7a7a8c', fontSize: 10, marginTop: 2 }}>
            Right-click or Esc to cancel
          </div>
        </div>
      )}

      {/* Layer toggle panel */}
      <div style={{
        position: 'absolute', bottom: 12, left: 12, zIndex: 1000,
        background: 'rgba(15,15,21,0.9)', border: '1px solid #252532',
        borderRadius: 6, padding: '8px 10px', fontSize: 10, color: '#a8a8bc',
        display: 'flex', flexDirection: 'column', gap: 3, userSelect: 'none',
      }}>
        {[
          { key: 'plates', label: 'Plate Boundaries', color: 'rgba(245, 158, 11, 0.5)', shape: 'line' },
          { key: 'earthquakes', label: 'Deep EQ (>300km)', color: '#8b5cf6', shape: 'dot' },
          { key: 'volcanoes', label: 'Active Volcanoes', color: '#ef4444', shape: 'dot' },
          { key: 'allVolcanoes', label: 'All Volcanoes', color: 'rgba(239,68,68,0.4)', shape: 'dot' },
          { key: 'stations', label: 'Mag Stations', color: '#4a9eff', shape: 'dot' },
          { key: 'monuments', label: 'Ancient Monuments', color: '#f59e0b', shape: 'dot' },
          { key: 'bearingLines', label: "Np\u2032 Bearing Lines", color: '#22c55e', shape: 'line' },
        ].map(item => (
          <label key={item.key} style={{
            display: 'flex', alignItems: 'center', gap: 6,
            cursor: 'pointer', opacity: layers[item.key] ? 1 : 0.4,
            transition: 'opacity 0.15s ease',
          }}>
            <input
              type="checkbox"
              checked={layers[item.key]}
              onChange={() => toggleLayer(item.key)}
              style={{ display: 'none' }}
            />
            {item.shape === 'dot' ? (
              <span style={{
                width: 8, height: 8, borderRadius: '50%',
                background: layers[item.key] ? item.color : '#333',
                display: 'inline-block', flexShrink: 0,
                transition: 'background 0.15s ease',
              }} />
            ) : (
              <span style={{
                width: 12, height: 2,
                background: layers[item.key] ? item.color : '#333',
                display: 'inline-block', flexShrink: 0,
                transition: 'background 0.15s ease',
              }} />
            )}
            <span style={{ fontSize: 10 }}>{item.label}</span>
          </label>
        ))}
        <div style={{ marginTop: 4, paddingTop: 4, borderTop: '1px solid #252532',
          fontSize: 9, color: '#7a7a8c', fontFamily: 'monospace' }}>
          {[...verified.values()].filter(v => v === 'verified').length} &#10003; {[...verified.values()].filter(v => v === 'plausible').length} ~ / {effectiveMonuments.length}
        </div>
        <button onClick={exportMeasurements} style={{
          marginTop: 4, padding: '3px 8px', fontSize: 9, fontFamily: 'monospace',
          fontWeight: 600, border: '1px solid #4a9eff', borderRadius: 4,
          background: 'rgba(74,158,255,0.08)', color: '#4a9eff', cursor: 'pointer',
          width: '100%',
        }}>EXPORT MEASUREMENTS</button>
        <button onClick={() => setAddPinMode(true)} style={{
          marginTop: 4, padding: '3px 8px', fontSize: 9, fontFamily: 'monospace',
          fontWeight: 600, border: '1px solid #22c55e', borderRadius: 4,
          background: 'rgba(34,197,94,0.08)', color: '#22c55e', cursor: 'pointer',
          width: '100%',
        }}>+ ADD PIN</button>
        {hiddenPins.size > 0 && (
          <div style={{ marginTop: 4, fontSize: 9, color: '#7a7a8c', fontFamily: 'monospace', textAlign: 'center' }}>
            {hiddenPins.size} hidden &mdash;{' '}
            <span onClick={() => {
              setHiddenPins(new Set());
              localStorage.removeItem('ecdo-watch-hidden-pins');
            }} style={{ color: '#4a9eff', cursor: 'pointer', textDecoration: 'underline' }}>restore</span>
          </div>
        )}
        <div style={{ display: 'flex', gap: 4, marginTop: 4 }}>
          <button onClick={() => {
            if (viewerRef.current) {
              viewerRef.current.camera.flyTo({
                destination: Cesium.Cartesian3.fromDegrees(170, 10, 20000000),
                duration: 1.0,
              });
            }
          }} style={{
            flex: 1, padding: '3px 8px', fontSize: 9, fontFamily: 'monospace',
            fontWeight: 600, border: '1px solid #7a7a8c', borderRadius: 4,
            background: 'transparent', color: '#7a7a8c', cursor: 'pointer',
          }} title="Reset camera to initial view">HOME</button>
          <button onClick={() => {
            if (viewerRef.current) {
              viewerRef.current.camera.flyTo({
                destination: Cesium.Cartesian3.fromDegrees(NP_PRIME.lng, NP_PRIME.lat, 5000000),
                duration: 1.0,
              });
            }
          }} style={{
            flex: 1, padding: '3px 8px', fontSize: 9, fontFamily: 'monospace',
            fontWeight: 600, border: '1px solid #22c55e', borderRadius: 4,
            background: 'rgba(34,197,94,0.08)', color: '#22c55e', cursor: 'pointer',
          }} title="Fly to Np' reference point">Np&#8242;</button>
          <button onClick={() => {
            if (viewerRef.current) {
              viewerRef.current.camera.flyTo({
                destination: Cesium.Cartesian3.fromDegrees(SP_PRIME.lng, SP_PRIME.lat, 5000000),
                duration: 1.0,
              });
            }
          }} style={{
            flex: 1, padding: '3px 8px', fontSize: 9, fontFamily: 'monospace',
            fontWeight: 600, border: '1px solid #f59e0b', borderRadius: 4,
            background: 'rgba(245,158,11,0.08)', color: '#f59e0b', cursor: 'pointer',
          }} title="Fly to Sp' (antipode of Np')">Sp&#8242;</button>
        </div>
      </div>

      {/* Monument list panel */}
      {(() => {
        // Search filter
        const query = monSearchQuery.toLowerCase();
        const filtered = effectiveMonuments.filter(m => {
          if (query && !m.name.toLowerCase().includes(query) && !(m.region || '').toLowerCase().includes(query)) return false;
          if (monFilterUnmeasured && measuredAxes.has(m.name)) return false;
          return true;
        });

        // Deviation helper
        const getDeviation = (m) => {
          const axis = measuredAxes.get(m.name);
          if (!axis) return null;
          const pin = resolvePin(m);
          const ideal = calcBearing(pin.lat, pin.lng, NP_PRIME.lat, NP_PRIME.lng);
          let deviation = Math.abs(axis.bearing - ideal);
          if (deviation > 180) deviation = 360 - deviation;
          if (deviation > 90) deviation = 180 - deviation;
          return deviation;
        };

        // Summary stats (computed over all monuments, not just filtered)
        const measuredCount = effectiveMonuments.filter(m => measuredAxes.has(m.name)).length;
        const confirmedCount = [...verified.values()].filter(v => v === 'verified').length;
        const allDeviations = effectiveMonuments
          .filter(m => { const p = resolvePin(m); return poleProximity(p.lat, p.lng).dist >= POLE_PROXIMITY_THRESHOLD; })
          .map(m => getDeviation(m)).filter(d => d !== null);
        const avgDev = allDeviations.length > 0 ? (allDeviations.reduce((a, b) => a + b, 0) / allDeviations.length) : null;

        // Sort by deviation (flat list) or group alphabetically
        let sortedFiltered;
        if (monSortBy === 'deviation') {
          sortedFiltered = [...filtered].sort((a, b) => {
            const da = getDeviation(a);
            const db = getDeviation(b);
            if (da === null && db === null) return a.name.localeCompare(b.name);
            if (da === null) return 1;
            if (db === null) return -1;
            return da - db;
          });
        }

        const groups = { verified: [], plausible: [], unconfirmed: [] };
        filtered.forEach(m => {
          const st = verified.get(m.name);
          if (st === 'verified') groups.verified.push(m);
          else if (st === 'plausible') groups.plausible.push(m);
          else groups.unconfirmed.push(m);
        });

        const sectionDefs = [
          { key: 'verified', label: 'Confirmed', color: '#22c55e', icon: '\u2713' },
          { key: 'plausible', label: 'Plausible', color: '#eab308', icon: '~' },
          { key: 'unconfirmed', label: 'Unconfirmed', color: '#7a7a8c', icon: '\u2022' },
        ];

        const renderMonumentItem = (m) => {
          const pin = resolvePin(m);
          const isSelected = selectedPoint && selectedPoint.mName === m.name;
          const axis = measuredAxes.get(m.name);
          const hasMeasurement = !!axis;
          return (
            <div
              key={m.name}
              onClick={() => {
                const mStatus = verified.get(m.name);
                setSelectedPoint({
                  type: 'monument', lat: pin.lat, lng: pin.lng,
                  mName: m.name, mRegion: m.region,
                  mAge: m.est_age, mNotes: m.notes,
                  mStatus, pinOverridden: pinOverrides.has(m.name),
                  _custom: !!m._custom,
                });
              }}
              style={{
                padding: '3px 12px 3px 20px', fontSize: 10, color: isSelected ? '#f59e0b' : '#a8a8bc',
                cursor: 'pointer', background: isSelected ? 'rgba(245,158,11,0.08)' : 'transparent',
                transition: 'background 0.1s',
                display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 4,
              }}
              onMouseEnter={e => { if (!isSelected) e.currentTarget.style.background = 'rgba(255,255,255,0.04)'; }}
              onMouseLeave={e => { if (!isSelected) e.currentTarget.style.background = 'transparent'; }}
            >
              <span style={{ display: 'flex', alignItems: 'center', gap: 4, overflow: 'hidden', minWidth: 0 }}>
                <span style={{
                  width: 6, height: 6, borderRadius: '50%', flexShrink: 0,
                  background: hasMeasurement ? '#00e5ff' : 'transparent',
                  border: hasMeasurement ? 'none' : '1px solid #444',
                }} />
                <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{m.name}</span>
              </span>
              {(() => {
                const prox = poleProximity(pin.lat, pin.lng);
                const nearPole = prox.dist < POLE_PROXIMITY_THRESHOLD;
                if (nearPole && !axis) return (
                  <span style={{ fontSize: 8, flexShrink: 0, fontFamily: 'monospace', color: '#f59e0b' }} title={`${prox.dist.toFixed(0)}\u00b0 from ${prox.pole} \u2014 azimuth unreliable`}>~{prox.pole}</span>
                );
                if (!axis) return null;
                const ideal = calcBearing(pin.lat, pin.lng, NP_PRIME.lat, NP_PRIME.lng);
                let deviation = Math.abs(axis.bearing - ideal);
                if (deviation > 180) deviation = 360 - deviation;
                if (deviation > 90) deviation = 180 - deviation;
                const devColor = nearPole ? '#7a7a8c' : deviation < 5 ? '#22c55e' : deviation < 15 ? '#eab308' : '#ef4444';
                return (
                  <span style={{ fontSize: 8, flexShrink: 0, fontFamily: 'monospace' }}>
                    <span style={{ color: nearPole ? '#7a7a8c' : '#00e5ff' }}>{axis.bearing.toFixed(0)}&deg;</span>
                    {' '}<span style={{ color: devColor }}>({nearPole ? '~' : ''}{deviation.toFixed(1)}&deg;)</span>
                    {nearPole && <span style={{ color: '#f59e0b', marginLeft: 2 }} title={`${prox.dist.toFixed(0)}\u00b0 from ${prox.pole}`}>*</span>}
                  </span>
                );
              })()}
            </div>
          );
        };
        return (
          <div style={{
            position: 'absolute', top: 12, left: 12, zIndex: 1000,
            userSelect: 'none',
          }}>
            <button onClick={() => setMonListOpen(p => !p)} style={{
              background: 'rgba(15,15,21,0.9)', border: '1px solid #252532',
              borderRadius: 6, padding: '6px 12px', fontSize: 10, fontFamily: 'monospace',
              color: '#f59e0b', cursor: 'pointer', fontWeight: 600,
              display: 'flex', alignItems: 'center', gap: 6,
            }}>
              <span style={{ fontSize: 8, transition: 'transform 0.15s', transform: monListOpen ? 'rotate(90deg)' : 'rotate(0deg)' }}>{'\u25B6'}</span>
              Monuments ({effectiveMonuments.length})
            </button>
            {monListOpen && (
              <div style={{
                marginTop: 4, background: 'rgba(15,15,21,0.95)', border: '1px solid #252532',
                borderRadius: 6, maxHeight: 420, overflowY: 'auto',
                minWidth: 220, maxWidth: 280,
              }}>
                {/* Search bar */}
                <div style={{ padding: '6px 8px', borderBottom: '1px solid #1a1a2e', position: 'sticky', top: 0, background: 'rgba(15,15,21,0.98)', zIndex: 1 }}>
                  <input
                    type="text"
                    placeholder="Search monuments..."
                    value={monSearchQuery}
                    onChange={e => setMonSearchQuery(e.target.value)}
                    style={{
                      width: '100%', padding: '4px 6px', fontSize: 10,
                      fontFamily: 'monospace', background: '#1a1a2e', border: '1px solid #252532',
                      borderRadius: 3, color: '#e8e8ed', outline: 'none', boxSizing: 'border-box',
                    }}
                  />
                </div>
                {/* Sort + filter controls */}
                <div style={{ padding: '4px 8px', borderBottom: '1px solid #1a1a2e', display: 'flex', gap: 4, alignItems: 'center', position: 'sticky', top: 33, background: 'rgba(15,15,21,0.98)', zIndex: 1 }}>
                  <button onClick={() => setMonSortBy(s => s === 'alpha' ? 'deviation' : 'alpha')} style={{
                    padding: '2px 6px', fontSize: 8, fontFamily: 'monospace', fontWeight: 600,
                    border: '1px solid #252532', borderRadius: 3,
                    background: monSortBy === 'deviation' ? 'rgba(0,229,255,0.12)' : 'transparent',
                    color: monSortBy === 'deviation' ? '#00e5ff' : '#7a7a8c', cursor: 'pointer',
                  }}>{monSortBy === 'alpha' ? 'A\u2193Z' : '\u0394\u2191'}</button>
                  <button onClick={() => setMonFilterUnmeasured(f => !f)} style={{
                    padding: '2px 6px', fontSize: 8, fontFamily: 'monospace', fontWeight: 600,
                    border: '1px solid #252532', borderRadius: 3,
                    background: monFilterUnmeasured ? 'rgba(245,158,11,0.12)' : 'transparent',
                    color: monFilterUnmeasured ? '#f59e0b' : '#7a7a8c', cursor: 'pointer',
                  }}>{monFilterUnmeasured ? 'UNMEASURED' : 'ALL'}</button>
                  <span style={{ fontSize: 8, color: '#7a7a8c', fontFamily: 'monospace', marginLeft: 'auto' }}>
                    {filtered.length}/{effectiveMonuments.length}
                  </span>
                </div>
                {/* Monument items */}
                {monSortBy === 'deviation' ? (
                  sortedFiltered.map(m => renderMonumentItem(m))
                ) : (
                  sectionDefs.map(sec => {
                    const items = groups[sec.key];
                    if (items.length === 0) return null;
                    const open = monSections[sec.key];
                    return (
                      <div key={sec.key}>
                        <div
                          onClick={() => setMonSections(p => ({ ...p, [sec.key]: !p[sec.key] }))}
                          style={{
                            padding: '4px 12px', fontSize: 10, fontFamily: 'monospace',
                            fontWeight: 700, color: sec.color, cursor: 'pointer',
                            display: 'flex', alignItems: 'center', gap: 6,
                            borderBottom: '1px solid #1a1a2e',
                          }}
                        >
                          <span style={{ fontSize: 7, transition: 'transform 0.15s', transform: open ? 'rotate(90deg)' : 'rotate(0deg)' }}>{'\u25B6'}</span>
                          {sec.icon} {sec.label} ({items.length})
                          {(() => {
                            const devs = items.map(m => getDeviation(m)).filter(d => d !== null);
                            if (devs.length === 0) return null;
                            const avg = devs.reduce((a, b) => a + b, 0) / devs.length;
                            return <span style={{ marginLeft: 'auto', fontSize: 8, color: avg < 10 ? '#22c55e' : '#eab308' }}>{avg.toFixed(1)}&deg;</span>;
                          })()}
                        </div>
                        {open && items.map(m => renderMonumentItem(m))}
                      </div>
                    );
                  })
                )}
                {/* Summary stats */}
                <div style={{
                  padding: '6px 8px', borderTop: '1px solid #1a1a2e',
                  fontSize: 9, fontFamily: 'monospace', color: '#7a7a8c',
                  display: 'flex', gap: 8, justifyContent: 'center',
                  position: 'sticky', bottom: 0, background: 'rgba(15,15,21,0.98)',
                }}>
                  <span><span style={{ color: '#00e5ff' }}>{measuredCount}</span> measured</span>
                  <span>avg: <span style={{ color: avgDev !== null && avgDev < 10 ? '#22c55e' : '#eab308' }}>{avgDev !== null ? avgDev.toFixed(1) + '\u00b0' : '\u2014'}</span></span>
                  <span><span style={{ color: '#22c55e' }}>{confirmedCount}</span> confirmed</span>
                </div>
              </div>
            )}
          </div>
        );
      })()}

      {/* Click info panel */}
      {selectedPoint && (() => {
        const d = selectedPoint;
        const borderColor = d.type === 'earthquake' ? '#8b5cf6'
          : d.type === 'volcano' ? '#ef4444'
          : d.type === 'monument' ? '#f59e0b'
          : d.type === 'np_prime' ? '#22c55e'
          : d.type === 'sp_prime' ? '#f59e0b'
          : '#4a9eff';
        return (
          <div style={{
            position: 'absolute', top: 12, right: 12, zIndex: 1000,
            background: 'rgba(15,15,21,0.95)', border: '1px solid #252532',
            borderLeft: `3px solid ${borderColor}`,
            borderRadius: 6, padding: '12px 16px', fontSize: 11, color: '#e8e8ed',
            minWidth: 180, maxWidth: 260, lineHeight: 1.6,
            fontFamily: 'Inter, system-ui, sans-serif',
          }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 6 }}>
              <span style={{ fontSize: 9, color: '#7a7a8c', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                {d.type === 'earthquake' ? 'Deep Earthquake'
                 : d.type === 'volcano' ? 'Volcano'
                 : d.type === 'monument' ? 'Ancient Monument'
                 : d.type === 'np_prime' ? 'Hypothesized Pole'
                 : d.type === 'sp_prime' ? 'Hypothesized Pole'
                 : 'Mag Station'}
              </span>
              <button
                onClick={(e) => { e.stopPropagation(); setSelectedPoint(null); }}
                style={{ background: 'transparent', border: 'none', color: '#7a7a8c', fontSize: 16, cursor: 'pointer', padding: 0, lineHeight: 1 }}
              >&#215;</button>
            </div>
            {d.type === 'earthquake' && (() => {
              let dateStr = d.date;
              if (d.datetime && d.datetime.includes('T')) {
                const dt = new Date(d.datetime);
                dateStr = dt.toISOString().replace('T', ' ').replace(/\.\d+Z$/, ' UTC');
              }
              return (
                <>
                  <div style={{ fontFamily: 'monospace', fontSize: 18, fontWeight: 700, color: '#c084fc', marginBottom: 4 }}>M{d.mag}</div>
                  <div style={{ color: '#a8a8bc' }}>Depth: <span style={{ color: '#e8e8ed', fontFamily: 'monospace' }}>{d.depth_km.toFixed(0)} km</span></div>
                  <div style={{ color: '#a8a8bc' }}>Date: <span style={{ color: '#e8e8ed', fontFamily: 'monospace' }}>{dateStr}</span></div>
                  <div style={{ color: '#7a7a8c', fontSize: 10, marginTop: 4, fontFamily: 'monospace' }}>{d.lat.toFixed(3)}, {d.lng.toFixed(3)}</div>
                </>
              );
            })()}
            {d.type === 'volcano' && (() => {
              const statusColor = d.vStatus === 'erupting' ? '#ef4444' : d.vStatus === 'elevated' ? '#f59e0b' : d.vStatus === 'holocene' ? '#a8a8bc' : '#7a7a8c';
              return (
                <>
                  <div style={{ fontFamily: 'monospace', fontSize: 15, fontWeight: 700, color: '#e8e8ed', marginBottom: 4 }}>{d.vName}</div>
                  <div style={{ color: '#a8a8bc' }}>Status: <span style={{ color: statusColor, fontWeight: 600, textTransform: 'uppercase', fontSize: 10 }}>{d.vStatus || 'active'}</span></div>
                  {d.vVei != null && <div style={{ color: '#a8a8bc' }}>VEI: <span style={{ color: '#e8e8ed', fontFamily: 'monospace' }}>{d.vVei}</span></div>}
                  {d.vStartDate && <div style={{ color: '#a8a8bc' }}>Eruption start: <span style={{ color: '#e8e8ed', fontFamily: 'monospace' }}>{d.vStartDate}</span></div>}
                  {d.vType && <div style={{ color: '#a8a8bc' }}>Type: <span style={{ color: '#e8e8ed' }}>{d.vType}</span></div>}
                  {d.vElevation != null && <div style={{ color: '#a8a8bc' }}>Elevation: <span style={{ color: '#e8e8ed', fontFamily: 'monospace' }}>{d.vElevation}m</span></div>}
                  {d.vLastEruption && <div style={{ color: '#a8a8bc' }}>Last eruption: <span style={{ color: '#e8e8ed', fontFamily: 'monospace' }}>{d.vLastEruption}</span></div>}
                  {d.vCountry && <div style={{ color: '#a8a8bc' }}>Country: <span style={{ color: '#e8e8ed' }}>{d.vCountry}</span></div>}
                  <div style={{ color: '#7a7a8c', fontSize: 10, marginTop: 4, fontFamily: 'monospace' }}>{d.lat.toFixed(3)}, {d.lng.toFixed(3)}</div>
                </>
              );
            })()}
            {d.type === 'station' && (
              <>
                <div style={{ fontFamily: 'monospace', fontSize: 18, fontWeight: 700, color: '#4a9eff', marginBottom: 4 }}>{d.sCode}</div>
                <div style={{ color: '#a8a8bc' }}>{d.sName}</div>
                <div style={{ color: '#7a7a8c', fontSize: 10, marginTop: 4, fontFamily: 'monospace' }}>{d.lat.toFixed(3)}, {d.lng.toFixed(3)}</div>
              </>
            )}
            {d.type === 'monument' && (() => {
              const idealBearing = calcBearing(d.lat, d.lng, NP_PRIME.lat, NP_PRIME.lng);
              const axis = measuredAxes.get(d.mName);
              const prox = poleProximity(d.lat, d.lng);
              const nearPole = prox.dist < POLE_PROXIMITY_THRESHOLD;
              return (
                <>
                  <div style={{ fontFamily: 'monospace', fontSize: 15, fontWeight: 700, color: '#f59e0b', marginBottom: 4 }}>{d.mName}</div>
                  <div style={{ color: '#a8a8bc' }}>Region: <span style={{ color: '#e8e8ed' }}>{d.mRegion}</span></div>
                  <div style={{ color: '#a8a8bc' }}>Est. age: <span style={{ color: '#e8e8ed', fontFamily: 'monospace' }}>{d.mAge}</span></div>
                  {d.mNotes && <div style={{ color: '#7a7a8c', fontSize: 10, marginTop: 4 }}>{d.mNotes}</div>}
                  {nearPole && (
                    <div style={{
                      marginTop: 6, padding: '4px 8px', background: 'rgba(245,158,11,0.1)',
                      border: '1px solid rgba(245,158,11,0.3)', borderRadius: 4,
                      fontSize: 9, color: '#f59e0b', fontFamily: 'monospace',
                    }}>
                      {prox.dist.toFixed(0)}&deg; from {prox.pole} &mdash; azimuth unreliable near pole
                    </div>
                  )}
                  <div style={{ color: '#a8a8bc', marginTop: 4 }}>Ideal bearing to Np&#8242;: <span style={{ color: nearPole ? '#7a7a8c' : '#f59e0b', fontFamily: 'monospace', fontWeight: 600 }}>{idealBearing.toFixed(1)}&deg;</span>{nearPole && <span style={{ color: '#7a7a8c', fontSize: 9 }}> (unreliable)</span>}</div>
                  {axis && (() => {
                    let deviation = Math.abs(axis.bearing - idealBearing);
                    if (deviation > 180) deviation = 360 - deviation;
                    if (deviation > 90) deviation = 180 - deviation;
                    const devColor = deviation < 5 ? '#22c55e' : deviation < 15 ? '#eab308' : '#ef4444';
                    return (
                      <>
                        <div style={{ color: '#a8a8bc' }}>Measured axis: <span style={{ color: '#00e5ff', fontFamily: 'monospace', fontWeight: 600 }}>{axis.bearing.toFixed(1)}&deg;</span></div>
                        <div style={{ color: '#a8a8bc' }}>Deviation: <span style={{ color: devColor, fontFamily: 'monospace', fontWeight: 600 }}>{deviation.toFixed(1)}&deg;</span>
                          <button onClick={() => {
                            setMeasuredAxes(prev => {
                              const next = new Map(prev);
                              next.delete(d.mName);
                              localStorage.setItem('ecdo-watch-axes', JSON.stringify(Object.fromEntries(next)));
                              return next;
                            });
                          }} style={{
                            marginLeft: 8, padding: '1px 5px', fontSize: 9, fontFamily: 'monospace',
                            border: '1px solid #7a7a8c', borderRadius: 3,
                            background: 'transparent', color: '#7a7a8c', cursor: 'pointer',
                          }}>x clear</button>
                        </div>
                      </>
                    );
                  })()}
                  <div style={{ color: '#7a7a8c', fontSize: 10, marginTop: 4, fontFamily: 'monospace' }}>
                    {d.lat.toFixed(3)}, {d.lng.toFixed(3)}
                    {d.pinOverridden && (
                      <span style={{ color: '#f59e0b', marginLeft: 6 }}>(moved)
                        <button onClick={() => {
                          setPinOverrides(prev => {
                            const next = new Map(prev);
                            next.delete(d.mName);
                            localStorage.setItem('ecdo-watch-pins', JSON.stringify(Object.fromEntries(next)));
                            return next;
                          });
                        }} style={{
                          marginLeft: 4, padding: '0 4px', fontSize: 8, fontFamily: 'monospace',
                          border: '1px solid #7a7a8c', borderRadius: 3,
                          background: 'transparent', color: '#7a7a8c', cursor: 'pointer',
                        }}>reset</button>
                      </span>
                    )}
                  </div>
                  <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap', marginTop: 8 }}>
                    {(() => {
                      const st = verified.get(d.mName);
                      const clr = st === 'verified' ? '#22c55e' : st === 'plausible' ? '#eab308' : '#7a7a8c';
                      const label = st === 'verified' ? '\u2713 VERIFIED' : st === 'plausible' ? '~ PLAUSIBLE' : 'MARK PLAUSIBLE';
                      return (
                        <button onClick={() => cycleVerified(d.mName)} style={{
                          padding: '4px 10px', fontSize: 10, fontFamily: 'monospace',
                          fontWeight: 600, border: `1px solid ${clr}`, borderRadius: 4,
                          background: st ? clr + '22' : 'transparent',
                          color: clr, cursor: 'pointer',
                        }}>{label}</button>
                      );
                    })()}
                    <button onClick={() => startPinReplace(d.mName, d.lat, d.lng)} style={{
                      padding: '4px 10px', fontSize: 10, fontFamily: 'monospace',
                      fontWeight: 600, border: '1px solid #f59e0b', borderRadius: 4,
                      background: 'rgba(245,158,11,0.08)', color: '#f59e0b', cursor: 'pointer',
                    }}>{d.pinOverridden ? 'MOVE PIN' : 'REPLACE PIN'}</button>
                    <button onClick={() => startAxisDrawing(d.mName, d.lat, d.lng)} style={{
                      padding: '4px 10px', fontSize: 10, fontFamily: 'monospace',
                      fontWeight: 600, border: '1px solid #00e5ff', borderRadius: 4,
                      background: 'rgba(0,229,255,0.08)', color: '#00e5ff', cursor: 'pointer',
                    }}>{axis ? 'REDRAW AXIS' : 'DRAW AXIS'}</button>
                    {removeConfirm === d.mName ? (
                      <>
                        <button onClick={() => { removePin(d.mName, d._custom); setRemoveConfirm(null); }} style={{
                          padding: '4px 10px', fontSize: 10, fontFamily: 'monospace',
                          fontWeight: 600, border: '1px solid #ef4444', borderRadius: 4,
                          background: 'rgba(239,68,68,0.25)', color: '#ef4444', cursor: 'pointer',
                        }}>CONFIRM</button>
                        <button onClick={() => setRemoveConfirm(null)} style={{
                          padding: '4px 10px', fontSize: 10, fontFamily: 'monospace',
                          fontWeight: 600, border: '1px solid #7a7a8c', borderRadius: 4,
                          background: 'transparent', color: '#7a7a8c', cursor: 'pointer',
                        }}>CANCEL</button>
                      </>
                    ) : (
                      <button onClick={() => setRemoveConfirm(d.mName)} style={{
                        padding: '4px 10px', fontSize: 10, fontFamily: 'monospace',
                        fontWeight: 600, border: '1px solid #ef4444', borderRadius: 4,
                        background: 'rgba(239,68,68,0.08)', color: '#ef4444', cursor: 'pointer',
                      }}>REMOVE</button>
                    )}
                  </div>
                </>
              );
            })()}
            {d.type === 'np_prime' && (
              <>
                <div style={{ fontFamily: 'monospace', fontSize: 15, fontWeight: 700, color: '#22c55e', marginBottom: 4 }}>Np&#8242; (Former North Pole)</div>
                <div style={{ color: '#a8a8bc' }}>ECDO Theory reference point</div>
                <div style={{ color: '#a8a8bc', marginTop: 4 }}>Position: <span style={{ color: '#e8e8ed', fontFamily: 'monospace' }}>14&deg;S, 31&deg;E</span></div>
                <div style={{ color: '#7a7a8c', fontSize: 10, marginTop: 4 }}>Hypothesized former/future North Pole per ECDO theory. ~200 ancient monuments allegedly align structural axes toward this point.</div>
              </>
            )}
            {d.type === 'sp_prime' && (
              <>
                <div style={{ fontFamily: 'monospace', fontSize: 15, fontWeight: 700, color: '#f59e0b', marginBottom: 4 }}>Sp&#8242; (Former South Pole)</div>
                <div style={{ color: '#a8a8bc' }}>Antipode of Np&#8242;</div>
                <div style={{ color: '#a8a8bc', marginTop: 4 }}>Position: <span style={{ color: '#e8e8ed', fontFamily: 'monospace' }}>14&deg;N, 149&deg;W</span></div>
                <div style={{ color: '#7a7a8c', fontSize: 10, marginTop: 4 }}>Monuments within ~20&deg; of either pole have unreliable azimuth measurements due to great circle degeneracy.</div>
              </>
            )}
          </div>
        );
      })()}

      {/* Add pin form overlay */}
      {addPinForm && (
        <div style={{
          position: 'absolute', top: 12, right: 12, zIndex: 1200,
          background: 'rgba(15,15,21,0.95)', border: '1px solid #22c55e',
          borderLeft: '3px solid #22c55e',
          borderRadius: 6, padding: '12px 16px', fontSize: 11, color: '#e8e8ed',
          minWidth: 220, maxWidth: 280,
          fontFamily: 'Inter, system-ui, sans-serif',
        }}>
          <div style={{ fontSize: 9, color: '#22c55e', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: 8, fontWeight: 700 }}>
            New Custom Pin
          </div>
          <div style={{ color: '#7a7a8c', fontSize: 10, marginBottom: 8, fontFamily: 'monospace' }}>
            {addPinForm.lat}, {addPinForm.lng}
          </div>
          <form onSubmit={(e) => {
            e.preventDefault();
            const fd = new FormData(e.target);
            const name = fd.get('name')?.trim();
            if (!name) return;
            const allNames = [...effectiveMonuments.map(m => m.name), ...customPins.map(p => p.name)];
            if (allNames.some(n => n.toLowerCase() === name.toLowerCase())) {
              setAddPinError('A pin with this name already exists');
              return;
            }
            setAddPinError(null);
            const pin = {
              name,
              lat: addPinForm.lat,
              lng: addPinForm.lng,
              region: fd.get('region')?.trim() || 'Custom',
              est_age: fd.get('est_age')?.trim() || 'Unknown',
              notes: fd.get('notes')?.trim() || '',
              _custom: true,
            };
            setCustomPins(prev => {
              const next = [...prev, pin];
              localStorage.setItem('ecdo-watch-custom-pins', JSON.stringify(next));
              return next;
            });
            setAddPinForm(null);
            setAddPinError(null);
          }}>
            <input name="name" placeholder="Name (required)" required autoFocus onChange={() => setAddPinError(null)} style={{
              width: '100%', marginBottom: 4, padding: '4px 6px', fontSize: 10,
              fontFamily: 'monospace', background: '#1a1a2e', border: addPinError ? '1px solid #ef4444' : '1px solid #252532',
              borderRadius: 3, color: '#e8e8ed', outline: 'none', boxSizing: 'border-box',
            }} />
            {addPinError && <div style={{ fontSize: 9, color: '#ef4444', marginBottom: 4, fontFamily: 'monospace' }}>{addPinError}</div>}
            <input name="region" placeholder="Region (optional)" style={{
              width: '100%', marginBottom: 4, padding: '4px 6px', fontSize: 10,
              fontFamily: 'monospace', background: '#1a1a2e', border: '1px solid #252532',
              borderRadius: 3, color: '#e8e8ed', outline: 'none', boxSizing: 'border-box',
            }} />
            <input name="est_age" placeholder="Est. age (optional)" style={{
              width: '100%', marginBottom: 4, padding: '4px 6px', fontSize: 10,
              fontFamily: 'monospace', background: '#1a1a2e', border: '1px solid #252532',
              borderRadius: 3, color: '#e8e8ed', outline: 'none', boxSizing: 'border-box',
            }} />
            <input name="notes" placeholder="Notes (optional)" style={{
              width: '100%', marginBottom: 8, padding: '4px 6px', fontSize: 10,
              fontFamily: 'monospace', background: '#1a1a2e', border: '1px solid #252532',
              borderRadius: 3, color: '#e8e8ed', outline: 'none', boxSizing: 'border-box',
            }} />
            <div style={{ display: 'flex', gap: 4 }}>
              <button type="submit" style={{
                flex: 1, padding: '4px 10px', fontSize: 10, fontFamily: 'monospace',
                fontWeight: 600, border: '1px solid #22c55e', borderRadius: 4,
                background: 'rgba(34,197,94,0.15)', color: '#22c55e', cursor: 'pointer',
              }}>SAVE</button>
              <button type="button" onClick={() => setAddPinForm(null)} style={{
                flex: 1, padding: '4px 10px', fontSize: 10, fontFamily: 'monospace',
                fontWeight: 600, border: '1px solid #7a7a8c', borderRadius: 4,
                background: 'transparent', color: '#7a7a8c', cursor: 'pointer',
              }}>CANCEL</button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
};

// Polar motion spiral + Chandler residual charts
const PolarMotionCharts = ({ polarMotionData }) => {
  const spiralRef = useRef(null);
  const chandlerRef = useRef(null);
  const spiralChartRef = useRef(null);
  const chandlerChartRef = useRef(null);

  useEffect(() => {
    if (!polarMotionData || !polarMotionData.labels || polarMotionData.labels.length === 0) return;

    // --- Chart 1: X/Y Spiral Plot ---
    if (spiralChartRef.current) spiralChartRef.current.destroy();

    const n = polarMotionData.labels.length;
    // Color gradient: blue (old) to orange (recent)
    const spiralPoints = polarMotionData.pm_x.map((x, i) => ({
      x: x,
      y: polarMotionData.pm_y[i],
    }));

    // Create gradient colors for each point
    const colors = polarMotionData.labels.map((_, i) => {
      const t = i / (n - 1); // 0..1
      const r = Math.round(74 + t * (245 - 74));
      const g = Math.round(158 + t * (158 - 158));
      const b = Math.round(255 + t * (11 - 255));
      return `rgb(${r},${g},${b})`;
    });

    spiralChartRef.current = new Chart(spiralRef.current.getContext('2d'), {
      type: 'scatter',
      data: {
        datasets: [{
          data: spiralPoints,
          pointBackgroundColor: colors,
          pointBorderColor: colors,
          pointRadius: 1,
          pointHoverRadius: 3,
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: true,
        aspectRatio: 1,
        plugins: {
          legend: { display: false },
          tooltip: {
            backgroundColor: '#16161f',
            borderColor: '#252532',
            borderWidth: 1,
            titleColor: '#e8e8ed',
            bodyColor: '#7a7a8c',
            callbacks: {
              label: (ctx) => {
                const idx = ctx.dataIndex;
                return `${polarMotionData.labels[idx]} | X: ${ctx.parsed.x.toFixed(4)}″ Y: ${ctx.parsed.y.toFixed(4)}″`;
              }
            }
          }
        },
        scales: {
          x: {
            title: { display: true, text: 'PM X (arcsec)', color: '#7a7a8c', font: { size: 10 } },
            grid: { color: '#1e1e2a' },
            ticks: { color: '#7a7a8c', font: { size: 9 } },
          },
          y: {
            title: { display: true, text: 'PM Y (arcsec)', color: '#7a7a8c', font: { size: 10 } },
            grid: { color: '#1e1e2a' },
            ticks: { color: '#7a7a8c', font: { size: 9 } },
          }
        }
      }
    });

    // --- Chart 2: Chandler Residual Time Series ---
    if (chandlerChartRef.current) chandlerChartRef.current.destroy();

    // Downsample for performance (every 3rd point)
    const step = 3;
    const dsLabels = polarMotionData.labels.filter((_, i) => i % step === 0);
    const dsX = polarMotionData.pm_x_chandler.filter((_, i) => i % step === 0);
    const dsY = polarMotionData.pm_y_chandler.filter((_, i) => i % step === 0);

    chandlerChartRef.current = new Chart(chandlerRef.current.getContext('2d'), {
      type: 'line',
      data: {
        labels: dsLabels,
        datasets: [
          {
            label: 'Chandler X',
            data: dsX,
            borderColor: '#4a9eff',
            borderWidth: 1.5,
            tension: 0.3,
            pointRadius: 0,
          },
          {
            label: 'Chandler Y',
            data: dsY,
            borderColor: '#f59e0b',
            borderWidth: 1.5,
            tension: 0.3,
            pointRadius: 0,
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            display: true,
            position: 'top',
            labels: { color: '#7a7a8c', boxWidth: 12, padding: 8, font: { size: 10 } }
          },
          tooltip: {
            backgroundColor: '#16161f',
            borderColor: '#252532',
            borderWidth: 1,
            titleColor: '#e8e8ed',
            bodyColor: '#7a7a8c',
          }
        },
        scales: {
          x: {
            grid: { display: false },
            ticks: { color: '#7a7a8c', font: { size: 9 }, maxTicksLimit: 8 },
          },
          y: {
            title: { display: true, text: 'arcsec', color: '#7a7a8c', font: { size: 10 } },
            grid: { color: '#1e1e2a' },
            ticks: { color: '#7a7a8c', font: { size: 9 } },
          }
        }
      }
    });

    return () => {
      if (spiralChartRef.current) spiralChartRef.current.destroy();
      if (chandlerChartRef.current) chandlerChartRef.current.destroy();
    };
  }, [polarMotionData]);

  if (!polarMotionData || !polarMotionData.labels || polarMotionData.labels.length === 0) {
    return (
      <div style={{ padding: 20, textAlign: 'center', color: '#7a7a8c', fontSize: 13 }}>
        Polar motion data not yet available. Run the data pipeline to generate.
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
      <div>
        <h4 style={{ fontSize: 12, color: '#7a7a8c', marginBottom: 8 }}>Polar Motion Spiral (10yr)</h4>
        <div style={{ maxWidth: 360, margin: '0 auto' }}>
          <canvas ref={spiralRef} />
        </div>
        <div style={{ fontSize: 10, color: '#7a7a8c', textAlign: 'center', marginTop: 4 }}>
          Color: <span style={{ color: '#4a9eff' }}>blue</span> = older → <span style={{ color: '#f59e0b' }}>orange</span> = recent
        </div>
      </div>
      <div>
        <h4 style={{ fontSize: 12, color: '#7a7a8c', marginBottom: 8 }}>Chandler Wobble Residual (~433d period)</h4>
        <div style={{ height: 160 }}>
          <canvas ref={chandlerRef} />
        </div>
      </div>
    </div>
  );
};

function ECDOWatchDashboard() {
  const [selectedTimeRange, setSelectedTimeRange] = useState('90d');
  const [historicalTimeRange, setHistoricalTimeRange] = useState(50);
  const [dataLoaded, setDataLoaded] = useState(false);
  const [kpData, setKpData] = useState(() => generateKpData());
  const [lodData, setLodData] = useState(() => generateLODData());
  const [c20Data, setC20Data] = useState({ labels: [], data: [] });
  const [magData, setMagData] = useState(() => generateMagData());
  const [aaData, setAaData] = useState(() => generateHistoricalAA(historicalTimeRange));
  const [pmData, setPmData] = useState(() => generateHistoricalPM(historicalTimeRange));
  const [coherenceData, setCoherenceData] = useState(null);
  const [seisData, setSeisData] = useState(null);
  const [volcData, setVolcData] = useState(null);
  const [polarMotionData, setPolarMotionData] = useState(null);
  const [seismicEvents, setSeismicEvents] = useState(null);
  const [compositeMetrics, setCompositeMetrics] = useState({ z: 0, flag: false, maxZ: 0 });
  const [statusLevel, setStatusLevel] = useState('NOMINAL');
  const [showStatusInfo, setShowStatusInfo] = useState(false);
  const [historicalExpanded, setHistoricalExpanded] = useState(false);
  const width = useWindowWidth();
  const [alignedData, setAlignedData] = useState(() => alignRecentData(kpData, lodData, magData));
  const [kpMetadata, setKpMetadata] = useState({});
  const [lodMetadata, setLodMetadata] = useState({});
  const [magMetadata, setMagMetadata] = useState({});

  // Load real data from JSON files when time range changes
  useEffect(() => {
    fetchDataFromJSON(selectedTimeRange).then(data => {
      if (data) {
        console.log(`Loaded data for ${selectedTimeRange}:`, { kpLabels: data.kpData.labels.length, lodLabels: data.lodData.labels.length, magLabels: data.magData.labels.length });
        setKpData(data.kpData);
        setLodData(data.lodData);
        setC20Data(data.c20Data);
        setAaData(data.aaData);
        setPmData(data.pmData);
        setMagData(data.magData);
        if (data.coherenceData) setCoherenceData(data.coherenceData);
        if (data.seisData) setSeisData(data.seisData);
        if (data.volcData) setVolcData(data.volcData);
        if (data.polarMotionData) setPolarMotionData(data.polarMotionData);
        if (data.seismicEventsData) setSeismicEvents(data.seismicEventsData);

        // Extract and store metadata
        setKpMetadata(data.kpData.metadata || {});
        setLodMetadata(data.lodData.metadata || {});
        setMagMetadata(data.magData.metadata || {});
      }
      setDataLoaded(true);
    }).catch(err => console.error('Error loading data:', err));
  }, [selectedTimeRange]);

  // Recalculate aligned data whenever individual datasets change
  useEffect(() => {
    const aligned = alignRecentData(kpData, lodData, magData);
    setAlignedData(aligned);
  }, [kpData, lodData, magData]);

  // Update historical data when time range changes
  useEffect(() => {
    setAaData(generateHistoricalAA(historicalTimeRange));
    setPmData(generateHistoricalPM(historicalTimeRange));
  }, [historicalTimeRange]);

  // Calculate composite z-score metrics dynamically
  useEffect(() => {
    if (alignedData.magData && alignedData.magData.composite && alignedData.magData.composite.length > 0) {
      const composite = alignedData.magData.composite;
      const validValues = composite.filter(v => v !== null);
      const recentValues = validValues.slice(-14); // Last 14 days with data
      if (recentValues.length > 0) {
        const maxAbsZ = Math.max(...recentValues.map(v => Math.abs(v)));
        const currentZ = composite[composite.length - 1];
        const flagged = maxAbsZ >= 2.5; // Flag if any recent value >= 2.5 sigma

        setCompositeMetrics({
          z: currentZ !== null ? currentZ.toFixed(2) : "—",
          flag: flagged,
          maxZ: maxAbsZ.toFixed(2)
        });
      }
    }
  }, [alignedData]);

  // Calculate watch status level from coherence data (or fall back to composite metrics)
  useEffect(() => {
    if (coherenceData && coherenceData.badge) {
      const badge = coherenceData.badge;
      if (badge === 'ORANGE') {
        setStatusLevel('WATCH');
      } else if (badge === 'YELLOW' || compositeMetrics.flag) {
        setStatusLevel('ELEVATED_DIAGNOSTIC');
      } else {
        setStatusLevel('NOMINAL');
      }
    } else if (compositeMetrics.flag) {
      setStatusLevel('ELEVATED_DIAGNOSTIC');
    } else {
      setStatusLevel('NOMINAL');
    }
  }, [compositeMetrics, coherenceData]);

  // Compute layout values
  const statusColorMap = { NOMINAL: '#10b981', ELEVATED_DIAGNOSTIC: '#f59e0b', WATCH: '#ef4444' };
  const statusColor = statusColorMap[statusLevel] || '#10b981';
  const gridCols4 = width >= 1000 ? 'repeat(4, 1fr)' : width >= 600 ? 'repeat(2, 1fr)' : '1fr';
  const gridCols3 = width >= 1000 ? 'repeat(3, 1fr)' : width >= 600 ? 'repeat(2, 1fr)' : '1fr';

  return (
    <div style={{ background: '#08080c', minHeight: '100vh', color: '#e8e8ed', fontFamily: 'Inter, system-ui, sans-serif' }}>
      <style dangerouslySetInnerHTML={{__html: '@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.5; } } .scene-tooltip { background: none !important; border: none !important; box-shadow: none !important; padding: 0 !important; }'}} />

      <div style={{ maxWidth: 1200, margin: '0 auto', padding: 20 }}>

        {/* Row 1: Merged Header Bar */}
        <div style={{
          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          background: '#0f0f15', border: '1px solid #252532',
          borderLeft: `4px solid ${statusColor}`,
          borderRadius: 8, padding: '8px 16px', marginBottom: 12,
          flexWrap: 'wrap', gap: 8, minHeight: 50,
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <h1 style={{ fontSize: 16, fontWeight: 700, margin: 0, whiteSpace: 'nowrap' }}>ECDO Watch</h1>
            <div style={{
              width: 10, height: 10, borderRadius: '50%', background: statusColor,
              animation: 'pulse 2s infinite', flexShrink: 0,
            }} />
            <span style={{ fontFamily: 'monospace', fontSize: 12, color: statusColor, fontWeight: 600 }}>{statusLevel}</span>
            <button
              onClick={() => setShowStatusInfo(!showStatusInfo)}
              style={{
                background: 'transparent', border: '1px solid #7a7a8c', color: '#7a7a8c',
                borderRadius: '50%', width: 18, height: 18, fontSize: 11, fontWeight: 'bold',
                cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center',
                padding: 0, transition: 'all 0.2s ease', flexShrink: 0,
              }}
            >i</button>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <DataFreshnessIndicator metadata={kpMetadata} />
            <a href="https://theethicalskeptic.com/2024/05/23/master-exothermic-core-mantle-decoupling-dzhanibekov-oscillation-theory/" target="_blank" rel="noopener noreferrer" style={{ color: '#4a9eff', textDecoration: 'none', fontSize: 10 }}>
              ECDO Theory
            </a>
          </div>
        </div>

        {/* Status info expandable panel */}
        {showStatusInfo && (
          <div style={{
            background: '#16161f', border: `1px solid ${statusColor}`, borderRadius: 8,
            padding: 16, marginBottom: 12, fontSize: 13, color: '#e8e8ed',
            borderLeft: `4px solid ${statusColor}`,
          }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 8 }}>
              <div>
                <strong style={{ color: statusColor }}>What does this mean?</strong>
                <p style={{ margin: '8px 0 0 0', color: '#a8a8bc' }}>
                  {statusLevel === 'WATCH' ? 'Multiple independent geophysical channels are showing correlated anomalies. This indicates a potential system-wide geophysical perturbation and warrants close observation.' :
                   statusLevel === 'ELEVATED_DIAGNOSTIC' ? 'One monitoring channel has detected a statistical anomaly. This may represent normal variability or the beginning of a multi-channel event.' :
                   'All monitored geophysical signals are within their normal historical ranges. No anomalies detected.'}
                </p>
                <strong style={{ color: statusColor, display: 'block', marginTop: 12 }}>What we monitor:</strong>
                <ul style={{ margin: '8px 0 0 0', paddingLeft: 20, color: '#a8a8bc' }}>
                  <li>External Forcing (Kp index) - Solar wind energy coupling</li>
                  <li>Earth Orientation (LOD) - Rotational dynamics</li>
                  <li>Ground Magnetometer - Multi-station magnetic field anomalies</li>
                  <li>Cross-channel Coherence - Correlated signals across independent systems</li>
                  <li>Deep Seismicity - Mantle stress via deep earthquakes (&gt;300km)</li>
                  <li>Volcanic Activity - Global eruption monitoring and dispersion</li>
                </ul>
                <div style={{ marginTop: 8, fontSize: 11, color: '#7a7a8c' }}>
                  Experimental analysis tool, NOT a prediction system
                </div>
              </div>
              <button onClick={() => setShowStatusInfo(false)} style={{
                background: 'transparent', border: 'none', color: '#7a7a8c',
                fontSize: 18, cursor: 'pointer', padding: 0, minWidth: 20,
              }}>&#215;</button>
            </div>
          </div>
        )}

        {/* Globe: Geophysical Spatial Monitor */}
        <div style={{ marginBottom: 12 }}>
          <div style={{ border: '1px solid #1e3a5f', borderRadius: 10, boxShadow: '0 0 20px rgba(74,158,255,0.05)' }}>
            <Card title="Geophysical Spatial Monitor" info={{
              description: "Interactive 3D globe showing deep earthquakes, active volcanoes, magnetometer stations, and ancient monument alignments toward Np\u2032 (hypothesized former North Pole at 14\u00b0S, 31\u00b0E). Use the layer toggles to show/hide each data layer.",
              lookingFor: [
                "Geographic clustering of deep EQ along subduction zones (Ring of Fire)",
                "Global dispersion of volcanic activity (widely separated eruptions suggest mantle-wide stress)",
                "Ancient monument structural axes converging toward Np\u2032 (31\u00b0E, 14\u00b0S)",
                "Polar motion spiral showing stable Chandler wobble amplitude (~0.1-0.2 arcsec)",
                "Changes in Chandler wobble amplitude or phase may indicate internal mass redistribution"
              ],
              dataSource: "USGS FDSN (earthquakes), Smithsonian GVP (volcanoes), IERS finals2000A (polar motion)"
            }}>
              <div style={{ height: 1000 }}>
                <GlobeView seismicEvents={seismicEvents} volcData={volcData} />
              </div>
            </Card>
          </div>
        </div>

        {/* Watch Analysis heading + time range selector */}
        <div style={{
          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          background: '#0f0f15', border: '1px solid #252532',
          borderRadius: 8, padding: '8px 16px', marginBottom: 12,
          flexWrap: 'wrap', gap: 8,
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <h3 style={{ fontSize: 14, fontWeight: 600, margin: 0, color: '#e8e8ed' }}>Watch Analysis</h3>
            <span style={{ fontSize: 10, color: '#7a7a8c' }}>Channel diagnostics</span>
          </div>
          <div style={{ display: 'flex', gap: 4 }}>
            {['30d', '90d', '1y', '5y', '10y'].map(range => (
              <button key={range} onClick={() => setSelectedTimeRange(range)} style={{
                background: selectedTimeRange === range ? '#4a9eff' : '#16161f',
                border: '1px solid #252532',
                color: selectedTimeRange === range ? '#fff' : '#7a7a8c',
                padding: '2px 8px', borderRadius: 3, fontSize: 9,
                fontFamily: 'monospace', cursor: 'pointer', transition: 'all 0.2s ease',
              }}>
                {range}
              </button>
            ))}
          </div>
        </div>

        {/* Polar Motion Charts */}
        <div style={{ marginBottom: 12 }}>
          <div style={{ background: '#0f0f15', border: '1px solid #252532', borderRadius: 8, padding: 16 }}>
            <PolarMotionCharts polarMotionData={polarMotionData} />
          </div>
        </div>

        {/* Row 2: Monitoring Panels - 4 column grid */}
        <div style={{ display: 'grid', gridTemplateColumns: gridCols4, gap: 12, marginBottom: 12 }}>

          {/* S1: Kp Gate */}
          <CompactCard step={1} title="Kp Gate" status="OPEN">
            <div style={{ height: 80 }}>
              <ChartComponent
                type="line"
                height={80}
                quietFlags={alignedData.kpData.is_quiet}
                data={{
                  labels: alignedData.kpData.labels,
                  datasets: [{
                    data: alignedData.kpData.data,
                    borderColor: '#4a9eff',
                    backgroundColor: 'rgba(74, 158, 255, 0.1)',
                    fill: true,
                    tension: 0.3,
                    pointRadius: 0,
                  }]
                }}
                options={{
                  ...darkThemeOptions,
                  scales: {
                    x: { ...darkThemeOptions.scales.x, display: false },
                    y: { ...darkThemeOptions.scales.y, ticks: { ...darkThemeOptions.scales.y.ticks, maxTicksLimit: 3 } },
                  }
                }}
              />
            </div>
            <div style={{ display: 'flex', gap: 4, marginTop: 8 }}>
              <CompactMetric
                label="Kp Max"
                value={(() => { const arr = (alignedData.kpData.data || []).filter(v => v != null); return arr.length > 0 ? Math.max(...arr).toFixed(1) : "\u2014"; })()}
                status={(() => { const arr = (alignedData.kpData.data || []).filter(v => v != null); const max = arr.length > 0 ? Math.max(...arr) : 0; return max >= 5 ? "negative" : max >= 4 ? "warning" : "positive"; })()}
              />
              <CompactMetric
                label="Kp Avg"
                value={(() => { const arr = (alignedData.kpData.data || []).filter(v => v != null); return arr.length > 0 ? (arr.reduce((a, b) => a + b, 0) / arr.length).toFixed(1) : "\u2014"; })()}
                status={(() => { const arr = (alignedData.kpData.data || []).filter(v => v != null); const avg = arr.length > 0 ? arr.reduce((a, b) => a + b, 0) / arr.length : 0; return avg >= 4 ? "warning" : "positive"; })()}
              />
              <CompactMetric
                label="Quiet"
                value={kpData && kpData.is_quiet ? `${kpData.is_quiet.filter(x => x).length}/${kpData.is_quiet.length}` : "\u2014"}
                status="positive"
              />
            </div>
          </CompactCard>

          {/* S2: EOP / LOD */}
          <CompactCard step={2} title="EOP / LOD" status="NOMINAL">
            <div style={{ height: 100 }}>
              <ChartComponent
                type="line"
                height={100}
                data={{
                  labels: lodData.labels || [],
                  datasets: [
                    {
                      data: lodData.z_lod || [],
                      borderColor: '#4a9eff',
                      borderWidth: 1.5,
                      tension: 0.3,
                      pointRadius: 0,
                    },
                    {
                      data: lodData.z_pm_speed || [],
                      borderColor: '#f59e0b',
                      borderWidth: 1.5,
                      tension: 0.3,
                      pointRadius: 0,
                    },
                    {
                      data: lodData.eop_composite || [],
                      borderColor: '#ffffff',
                      borderWidth: 2,
                      tension: 0.3,
                      pointRadius: 0,
                    }
                  ]
                }}
                options={{
                  ...darkThemeOptions,
                  scales: {
                    x: { ...darkThemeOptions.scales.x, display: false },
                    y: { ...darkThemeOptions.scales.y, ticks: { ...darkThemeOptions.scales.y.ticks, maxTicksLimit: 3 } },
                  }
                }}
              />
            </div>
            <div style={{ display: 'flex', gap: 4, marginTop: 8 }}>
              <CompactMetric
                label="LOD z"
                value={(() => { const arr = lodData.z_lod || []; const v = arr[arr.length - 1]; return v != null ? v.toFixed(2) : "\u2014"; })()}
                status={(() => { const arr = lodData.z_lod || []; const v = arr[arr.length - 1]; return v != null && Math.abs(v) >= 2.5 ? "warning" : "positive"; })()}
              />
              <CompactMetric
                label="PM z"
                value={(() => { const arr = lodData.z_pm_speed || []; const v = arr[arr.length - 1]; return v != null ? v.toFixed(2) : "\u2014"; })()}
                status={(() => { const arr = lodData.z_pm_speed || []; const v = arr[arr.length - 1]; return v != null && Math.abs(v) >= 2.5 ? "warning" : "positive"; })()}
              />
              <CompactMetric
                label="EOP"
                value={(() => { const arr = lodData.eop_composite || []; const v = arr[arr.length - 1]; return v != null ? v.toFixed(2) : "\u2014"; })()}
                status={(() => { const arr = lodData.eop_composite || []; const v = arr[arr.length - 1]; return v != null && Math.abs(v) >= 2.5 ? "warning" : "positive"; })()}
              />
            </div>
          </CompactCard>

          {/* S4: Magnetometer (visual order: after EOP) */}
          <CompactCard step={4} title="Magnetometer" status="NOMINAL">
            <div style={{ height: 100 }}>
              <ChartComponent
                type="line"
                height={100}
                data={{
                  labels: alignedData.magData.labels,
                  datasets: [
                    {
                      data: alignedData.magData.bou,
                      borderColor: 'rgba(74, 158, 255, 0.15)',
                      borderWidth: 1,
                      tension: 0.3,
                      pointRadius: 0,
                    },
                    {
                      data: alignedData.magData.frd,
                      borderColor: 'rgba(245, 158, 11, 0.15)',
                      borderWidth: 1,
                      tension: 0.3,
                      pointRadius: 0,
                    },
                    {
                      data: alignedData.magData.brw,
                      borderColor: 'rgba(16, 185, 129, 0.15)',
                      borderWidth: 1,
                      tension: 0.3,
                      pointRadius: 0,
                    },
                    {
                      data: alignedData.magData.hon,
                      borderColor: 'rgba(139, 92, 246, 0.15)',
                      borderWidth: 1,
                      tension: 0.3,
                      pointRadius: 0,
                    },
                    {
                      data: alignedData.magData.composite,
                      borderColor: '#ffffff',
                      borderWidth: 2,
                      tension: 0.3,
                      pointRadius: 0,
                    }
                  ]
                }}
                options={{
                  ...darkThemeOptions,
                  scales: {
                    x: { ...darkThemeOptions.scales.x, display: false },
                    y: { ...darkThemeOptions.scales.y, ticks: { ...darkThemeOptions.scales.y.ticks, maxTicksLimit: 3 } },
                  }
                }}
              />
            </div>
            <div style={{ display: 'flex', gap: 4, marginTop: 8 }}>
              <CompactMetric label="Comp z" value={compositeMetrics.z} status={Math.abs(parseFloat(compositeMetrics.z)) >= 2.5 ? "negative" : "positive"} />
              <CompactMetric label="Max 14d" value={compositeMetrics.maxZ} status={compositeMetrics.flag ? "warning" : "positive"} />
              <CompactMetric label="Flag" value={compositeMetrics.flag ? "\u26a0" : "\u2713"} status={compositeMetrics.flag ? "warning" : "positive"} />
            </div>
          </CompactCard>

          {/* S3: C20 */}
          <CompactCard step={3} title="C20 Mass" status="OK" subtitle={c20Data && c20Data.labels ? `${c20Data.labels.length}d` : ''}>
            <div style={{ height: 80 }}>
              <ChartComponent
                type="line"
                height={80}
                data={{
                  labels: c20Data && c20Data.labels ? c20Data.labels : [],
                  datasets: [{
                    data: c20Data && c20Data.data ? c20Data.data : [],
                    borderColor: '#10b981',
                    tension: 0.3,
                    pointRadius: 0,
                  }]
                }}
                options={{
                  ...darkThemeOptions,
                  scales: {
                    x: { ...darkThemeOptions.scales.x, display: false },
                    y: { ...darkThemeOptions.scales.y, ticks: { ...darkThemeOptions.scales.y.ticks, maxTicksLimit: 3 } },
                  }
                }}
              />
            </div>
            <div style={{ display: 'flex', gap: 4, marginTop: 8 }}>
              <CompactMetric label="C20 z" value={c20Data && c20Data.data && c20Data.data.length > 0 && c20Data.data[c20Data.data.length - 1] !== null ? c20Data.data[c20Data.data.length - 1].toFixed(2) : "\u2014"} status="positive" />
              <CompactMetric label="vs GIA" value="Normal" status="positive" />
            </div>
          </CompactCard>
        </div>

        {/* Row 4: Analysis Panels - 3 column grid */}
        <div style={{ display: 'grid', gridTemplateColumns: gridCols3, gap: 12, marginBottom: 12 }}>

          {/* S5: Coherence */}
          <CompactCard step={5} title="Coherence" status={coherenceData && coherenceData.badge === 'ORANGE' ? 'ELEVATED' : 'NOMINAL'}>
            {coherenceData && coherenceData.labels && coherenceData.labels.length > 0 ? (
              <>
                <div style={{ display: 'flex', gap: 4, marginBottom: 8 }}>
                  <CompactMetric
                    label="Quiet Days"
                    value={`${coherenceData.quiet_day_count}/${coherenceData.total_days}`}
                    status="positive"
                  />
                  <CompactMetric
                    label="Score"
                    value={coherenceData.latest_watch_score != null ? coherenceData.latest_watch_score.toFixed(0) : "\u2014"}
                    status={coherenceData.badge === 'GREEN' ? 'positive' : coherenceData.badge === 'YELLOW' ? 'warning' : coherenceData.badge === 'ORANGE' ? 'negative' : undefined}
                  />
                  <CompactMetric
                    label="Badge"
                    value={coherenceData.badge}
                    status={coherenceData.badge === 'GREEN' ? 'positive' : coherenceData.badge === 'YELLOW' ? 'warning' : coherenceData.badge === 'ORANGE' ? 'negative' : undefined}
                  />
                </div>
                <div style={{ height: 100, marginBottom: 8 }}>
                  <ChartComponent
                    type="line"
                    height={100}
                    data={{
                      labels: coherenceData.labels,
                      datasets: [
                        {
                          label: 'EOP',
                          data: coherenceData.eop_composite,
                          borderColor: '#4a9eff',
                          borderWidth: 1.5,
                          tension: 0.3,
                          pointRadius: 0,
                        },
                        {
                          label: 'MAG',
                          data: coherenceData.mag_composite,
                          borderColor: '#f59e0b',
                          borderWidth: 1.5,
                          tension: 0.3,
                          pointRadius: 0,
                        }
                      ]
                    }}
                    options={{
                      ...darkThemeOptions,
                      plugins: {
                        ...darkThemeOptions.plugins,
                        legend: {
                          display: true,
                          position: 'top',
                          labels: { color: '#7a7a8c', boxWidth: 8, padding: 6, font: { size: 9 } }
                        }
                      },
                      scales: {
                        x: { ...darkThemeOptions.scales.x, display: true, ticks: { maxTicksLimit: 5 } },
                        y: { ...darkThemeOptions.scales.y },
                      }
                    }}
                  />
                </div>
                <div style={{ height: 60, marginBottom: 8 }}>
                  <ChartComponent
                    type="line"
                    height={60}
                    data={{
                      labels: coherenceData.labels,
                      quietFlags: coherenceData.quiet,
                      datasets: [{
                        data: coherenceData.watch_score,
                        borderColor: '#10b981',
                        backgroundColor: 'rgba(16, 185, 129, 0.1)',
                        fill: true,
                        tension: 0.3,
                        pointRadius: 0,
                      }]
                    }}
                    options={{
                      ...darkThemeOptions,
                      plugins: { ...darkThemeOptions.plugins, legend: { display: false } },
                      scales: {
                        x: { ...darkThemeOptions.scales.x, display: false },
                        y: { ...darkThemeOptions.scales.y, min: 0, max: 100 },
                      }
                    }}
                    quietFlags={coherenceData.quiet}
                  />
                </div>
                <div style={{ display: 'flex', gap: 4 }}>
                  <CompactMetric
                    label="EOP&#8596;MAG r"
                    value={coherenceData.correlation != null ? coherenceData.correlation.toFixed(2) : "n/a"}
                    status={coherenceData.correlation != null && Math.abs(coherenceData.correlation) >= 0.5 ? "warning" : "positive"}
                  />
                  <CompactMetric
                    label="N quiet"
                    value={`${coherenceData.quiet_day_count}`}
                    status={coherenceData.quiet_day_count >= 10 ? "positive" : "warning"}
                  />
                </div>
              </>
            ) : (
              <div style={{ padding: 16, textAlign: 'center', color: '#7a7a8c', fontSize: 11 }}>
                Coherence data not yet available.
              </div>
            )}
          </CompactCard>

          {/* S6: Deep Seismicity */}
          <CompactCard step={6} title="Deep Seismicity" status={(() => {
            if (!seisData || !seisData.z_eq_count) return 'NOMINAL';
            const recent = seisData.z_eq_count.slice(-14).filter(v => v != null);
            const maxZ = recent.length > 0 ? Math.max(...recent.map(v => Math.abs(v))) : 0;
            return maxZ >= 2.5 ? 'ELEVATED' : 'NOMINAL';
          })()}>
            {seisData && seisData.labels && seisData.labels.length > 0 ? (
              <>
                <div style={{ height: 120 }}>
                  <ChartComponent
                    type="line"
                    height={120}
                    data={{
                      labels: seisData.labels,
                      datasets: [
                        {
                          label: 'Daily deep EQ',
                          data: seisData.eq_count,
                          borderColor: '#8b5cf6',
                          backgroundColor: 'rgba(139, 92, 246, 0.1)',
                          fill: true,
                          borderWidth: 1.5,
                          tension: 0.3,
                          pointRadius: 0,
                        },
                        {
                          label: '30d avg',
                          data: seisData.rolling_30d_count,
                          borderColor: '#ffffff',
                          borderWidth: 2,
                          borderDash: [5, 3],
                          tension: 0.3,
                          pointRadius: 0,
                        }
                      ]
                    }}
                    options={{
                      ...darkThemeOptions,
                      plugins: {
                        ...darkThemeOptions.plugins,
                        legend: {
                          display: true,
                          position: 'top',
                          labels: { color: '#7a7a8c', boxWidth: 8, padding: 6, font: { size: 9 } }
                        }
                      },
                      scales: {
                        x: { ...darkThemeOptions.scales.x, display: true, ticks: { maxTicksLimit: 5 } },
                        y: { ...darkThemeOptions.scales.y },
                      }
                    }}
                  />
                </div>
                <div style={{ display: 'flex', gap: 4, marginTop: 8 }}>
                  <CompactMetric
                    label="30d avg"
                    value={(() => {
                      const arr = seisData.rolling_30d_count || [];
                      const v = arr[arr.length - 1];
                      return v != null ? v.toFixed(1) : "\u2014";
                    })()}
                    status="positive"
                  />
                  <CompactMetric
                    label="Max z 14d"
                    value={(() => {
                      const arr = (seisData.z_eq_count || []).slice(-14).filter(v => v != null);
                      return arr.length > 0 ? Math.max(...arr.map(v => Math.abs(v))).toFixed(2) : "\u2014";
                    })()}
                    status={(() => {
                      const arr = (seisData.z_eq_count || []).slice(-14).filter(v => v != null);
                      const maxZ = arr.length > 0 ? Math.max(...arr.map(v => Math.abs(v))) : 0;
                      return maxZ >= 2.5 ? "warning" : "positive";
                    })()}
                  />
                  <CompactMetric
                    label="Energy"
                    value={(() => {
                      const arr = (seisData.energy_log10 || []).slice(-30).filter(v => v != null);
                      if (arr.length === 0) return "\u2014";
                      return (arr.reduce((a, b) => a + b, 0) / arr.length).toFixed(1);
                    })()}
                    status="positive"
                  />
                </div>
              </>
            ) : (
              <div style={{ padding: 16, textAlign: 'center', color: '#7a7a8c', fontSize: 11 }}>
                Deep seismicity data not yet available.
              </div>
            )}
          </CompactCard>

          {/* S7: Volcanic */}
          <CompactCard step={7} title="Volcanic" status={(() => {
            if (!volcData || !volcData.z_active_count) return 'NOMINAL';
            const recent = volcData.z_active_count.filter(v => v != null);
            const latest = recent.length > 0 ? recent[recent.length - 1] : 0;
            return Math.abs(latest) >= 2.0 ? 'ELEVATED' : 'NOMINAL';
          })()}>
            {volcData && volcData.labels && volcData.labels.length > 0 ? (
              <>
                <div style={{ height: 100 }}>
                  <ChartComponent
                    type="bar"
                    height={100}
                    data={{
                      labels: volcData.labels,
                      datasets: [{
                        data: volcData.active_count,
                        backgroundColor: volcData.z_active_count
                          ? volcData.z_active_count.map(z => z != null && Math.abs(z) >= 2.0 ? '#ef4444' : '#f59e0b')
                          : '#f59e0b',
                        borderRadius: 2,
                      }]
                    }}
                    options={{
                      ...darkThemeOptions,
                      plugins: { ...darkThemeOptions.plugins, legend: { display: false } },
                      scales: {
                        x: { ...darkThemeOptions.scales.x, display: true, ticks: { maxTicksLimit: 5 } },
                        y: { ...darkThemeOptions.scales.y, beginAtZero: true },
                      }
                    }}
                  />
                </div>
                <div style={{ display: 'flex', gap: 4, marginTop: 8 }}>
                  <CompactMetric
                    label="Active"
                    value={(() => {
                      const arr = volcData.active_count || [];
                      return arr.length > 0 ? arr[arr.length - 1] : "\u2014";
                    })()}
                    status="positive"
                  />
                  <CompactMetric
                    label="New 30d"
                    value={(() => {
                      const arr = volcData.new_eruptions || [];
                      return arr.length > 0 ? arr[arr.length - 1] : "\u2014";
                    })()}
                    status={(() => {
                      const arr = volcData.new_eruptions || [];
                      const v = arr.length > 0 ? arr[arr.length - 1] : 0;
                      return v >= 3 ? "warning" : "positive";
                    })()}
                  />
                  <CompactMetric
                    label="Disp km"
                    value={(() => {
                      const arr = volcData.dispersion_km || [];
                      const v = arr.length > 0 ? arr[arr.length - 1] : null;
                      return v != null ? Math.round(v).toLocaleString() : "\u2014";
                    })()}
                    status="positive"
                  />
                </div>
                {volcData.current_volcanoes && volcData.current_volcanoes.length > 0 && (
                  <div style={{ marginTop: 8, padding: 8, background: '#16161f', borderRadius: 4, fontSize: 10, color: '#a8a8bc', maxHeight: 60, overflowY: 'auto' }}>
                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4 }}>
                      {volcData.current_volcanoes.slice(0, 15).map((v, idx) => (
                        <span key={idx} style={{
                          padding: '1px 6px', borderRadius: 3, fontSize: 9,
                          background: v.status === 'erupting' ? 'rgba(239,68,68,0.2)' : 'rgba(107,114,128,0.2)',
                          color: v.status === 'erupting' ? '#ef4444' : '#7a7a8c',
                        }}>
                          {v.name}
                        </span>
                      ))}
                      {volcData.current_volcanoes.length > 15 && (
                        <span style={{ color: '#7a7a8c', fontSize: 9 }}>+{volcData.current_volcanoes.length - 15}</span>
                      )}
                    </div>
                  </div>
                )}
              </>
            ) : (
              <div style={{ padding: 16, textAlign: 'center', color: '#7a7a8c', fontSize: 11 }}>
                Volcanic data not yet available.
              </div>
            )}
          </CompactCard>
        </div>

        {/* Row 5: Historical Context (collapsible) */}
        <div style={{ background: '#0f0f15', border: '1px solid #252532', borderRadius: 8, overflow: 'hidden', marginBottom: 12 }}>
          <div
            onClick={() => setHistoricalExpanded(!historicalExpanded)}
            style={{
              display: 'flex', alignItems: 'center', gap: 8,
              padding: '12px 16px', cursor: 'pointer',
              background: '#16161f', userSelect: 'none',
            }}
          >
            <span style={{ fontSize: 10, color: '#7a7a8c', transition: 'transform 0.2s', display: 'inline-block', transform: historicalExpanded ? 'rotate(90deg)' : 'rotate(0deg)' }}>&#9654;</span>
            <h3 style={{ fontSize: 14, fontWeight: 600, margin: 0, color: '#e8e8ed' }}>Century-Scale Historical Context</h3>
          </div>
          {historicalExpanded && (
            <div style={{ padding: 16 }}>
              <div style={{ display: 'flex', gap: 8, marginBottom: 16, flexWrap: 'wrap' }}>
                {[10, 50, 100, 150].map(y => (
                  <button key={y} onClick={() => setHistoricalTimeRange(y)} style={{
                    background: historicalTimeRange === y ? '#4a9eff' : '#16161f',
                    border: '1px solid #252532', color: historicalTimeRange === y ? '#fff' : '#7a7a8c',
                    padding: '4px 12px', borderRadius: 4, fontSize: 11, fontFamily: 'monospace', cursor: 'pointer',
                  }}>{y}Y</button>
                ))}
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: 16 }}>
                <div>
                  <h4 style={{ fontSize: 12, color: '#7a7a8c', marginBottom: 8 }}>Geomagnetic Ap Index (since 1932)</h4>
                  <div style={{ height: 160 }}>
                    <ChartComponent
                      type="line"
                      height={160}
                      data={{
                        labels: aaData.labels,
                        datasets: [{
                          data: aaData.data,
                          borderColor: '#f59e0b',
                          backgroundColor: 'rgba(245, 158, 11, 0.1)',
                          fill: true, tension: 0.3, pointRadius: 0,
                        }]
                      }}
                      options={{
                        ...darkThemeOptions,
                        scales: {
                          ...darkThemeOptions.scales,
                          x: { ...darkThemeOptions.scales.x, display: true, ticks: { maxTicksLimit: 10 } },
                          y: { ...darkThemeOptions.scales.y },
                        }
                      }}
                    />
                  </div>
                </div>
                <div>
                  <h4 style={{ fontSize: 12, color: '#7a7a8c', marginBottom: 8 }}>Polar Motion Amplitude (since 1846)</h4>
                  <div style={{ height: 160 }}>
                    <ChartComponent
                      type="line"
                      height={160}
                      data={{
                        labels: pmData.labels,
                        datasets: [{
                          data: pmData.data,
                          borderColor: '#10b981',
                          backgroundColor: 'rgba(16, 185, 129, 0.1)',
                          fill: true, tension: 0.3, pointRadius: 0,
                        }]
                      }}
                      options={{
                        ...darkThemeOptions,
                        scales: {
                          ...darkThemeOptions.scales,
                          x: { ...darkThemeOptions.scales.x, display: true, ticks: { maxTicksLimit: 10 } },
                          y: { ...darkThemeOptions.scales.y },
                        }
                      }}
                    />
                  </div>
                </div>
              </div>
              <div style={{ display: 'flex', gap: 16, marginTop: 16, flexWrap: 'wrap' }}>
                <Metric label="Ap Record" value="1932&#8211;Now" />
                <Metric label="PM Record" value="1846&#8211;Now" />
                <Metric label="LOD Record" value="1623&#8211;Now" />
                <Metric label="Current Regime" value="Within Bounds" status="positive" />
              </div>
              <div style={{ marginTop: 16, padding: 12, background: '#16161f', borderRadius: 6, fontSize: 11, color: '#7a7a8c' }}>
                <strong>Data sources:</strong> Ap index from GFZ (1932&#8211;present); Polar motion from IERS C01 (1846&#8211;present); LOD from IERS (yearly since 1623).
              </div>
            </div>
          )}
        </div>

        <DataSourceFooter kpMetadata={kpMetadata} lodMetadata={lodMetadata} magMetadata={magMetadata} />

        <footer style={{ marginTop: 16, paddingTop: 12, borderTop: '1px solid #252532', fontSize: 11, color: '#7a7a8c', textAlign: 'left' }}>
          Experimental analysis tool, NOT a prediction system. Watch levels indicate statistical anomalies relative to historical baselines.
        </footer>
      </div>
    </div>
  );
}
